/// Saves a password login's session, as the app does.
fn write_saved_session(
    local_app_data: &Path,
    homeserver_url: &str,
) -> Result<PathBuf, Box<dyn std::error::Error>> {
    write_saved_session_payload(
        local_app_data,
        &serde_json::json!({
            "version": 2,
            "homeserver_url": homeserver_url,
            "session": core_stored_session(),
        }),
    )
}

/// Saves a session the way mirx did before sessions recorded how they
/// signed in.
fn write_version_1_saved_session(
    local_app_data: &Path,
    homeserver_url: &str,
) -> Result<PathBuf, Box<dyn std::error::Error>> {
    write_saved_session_payload(
        local_app_data,
        &serde_json::json!({
            "version": 1,
            "homeserver_url": homeserver_url,
            "session": {
                "user_id": "@alice:example",
                "device_id": "DEVICE",
                "access_token": "secret-token",
                "refresh_token": "refresh-token"
            }
        }),
    )
}

fn write_saved_session_payload(
    local_app_data: &Path,
    payload: &serde_json::Value,
) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let path = session_file_path(local_app_data);
    let parent = path
        .parent()
        .ok_or_else(|| format!("missing parent for {}", path.display()))?;
    fs::create_dir_all(parent)?;
    let payload = serde_json::to_vec(payload)?;
    let protected = dpapi::protect(&payload, "mirx saved session test", SESSION_DPAPI_ENTROPY)?;
    let mut bytes = Vec::with_capacity(PROTECTED_SESSION_MAGIC.len() + protected.len());
    bytes.extend_from_slice(PROTECTED_SESSION_MAGIC);
    bytes.extend_from_slice(&protected);
    fs::write(&path, bytes)?;
    Ok(path)
}

/// The session file the app saved, unprotected.
fn read_saved_session(
    local_app_data: &Path,
) -> Result<serde_json::Value, Box<dyn std::error::Error>> {
    let bytes = fs::read(session_file_path(local_app_data))?;
    let protected = bytes
        .strip_prefix(PROTECTED_SESSION_MAGIC)
        .ok_or("saved session is not protected")?;
    Ok(serde_json::from_slice(&dpapi::unprotect(
        protected,
        SESSION_DPAPI_ENTROPY,
    )?)?)
}

/// The homeserver URL the app saved with its session.
fn saved_session_homeserver_url(
    local_app_data: &Path,
) -> Result<String, Box<dyn std::error::Error>> {
    Ok(read_saved_session(local_app_data)?["homeserver_url"]
        .as_str()
        .ok_or("saved session has no homeserver_url")?
        .to_owned())
}

fn fixture_state_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/ui-states")
        .join(name)
}

/// The `reactions.json` fixture, signed in as `user_id`, whose messages
/// become the user's own.
fn reactions_fixture_signed_in_as(user_id: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut events: Vec<serde_json::Value> =
        serde_json::from_str(&fs::read_to_string(fixture_state_path("reactions.json"))?)?;
    assert_eq!(events[0], serde_json::json!("Started"));
    events.insert(
        1,
        serde_json::to_value(Event::LoggedIn {
            session: CoreStoredSession {
                user_id: user_id.to_owned(),
                ..core_stored_session()
            },
            homeserver_url: "https://matrix.example/".to_owned(),
        })?,
    );
    Ok(serde_json::to_string(&events)?)
}

fn fixture_update_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/ui-state-updates")
        .join(name)
}

fn write_state_file(events: &[Event]) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let state_path = unique_state_path();
    fs::write(&state_path, serde_json::to_vec(events)?)?;
    Ok(state_path)
}

struct MockBackfillHomeserver {
    base_url: String,
    faults: Arc<MockFaults>,
    /// The bodies of the `read_markers` requests, in arrival order.
    read_markers: Arc<Mutex<Vec<serde_json::Value>>>,
    /// `!beta:example`'s sync timeline, which every `/sync` serves whole.
    timeline: Arc<Mutex<Vec<serde_json::Value>>>,
    /// What the user's presence went through: the bodies of the presence
    /// `PUT`s, in arrival order. A `GET` answers the last one's presence.
    presence_puts: Arc<Mutex<Vec<serde_json::Value>>>,
    /// Each `/sync`'s `set_presence`, in arrival order.
    sync_presence: Arc<Mutex<Vec<Option<String>>>>,
    /// The bodies of the typing notices, in arrival order.
    typing: Arc<Mutex<Vec<serde_json::Value>>>,
    /// The `/logout` requests it got.
    logouts: Arc<AtomicUsize>,
    /// Other users' presence, which every `/sync` serves.
    presence: Arc<Mutex<MockPresence>>,
    /// Every request it got, as `GET /path` without the query, in arrival
    /// order.
    requests: Arc<Mutex<Vec<String>>>,
    /// Beta's settings writes, as `PUT state/m.room.topic/` (the path
    /// after the room's) or `PUT directory`, with their bodies, in arrival
    /// order.
    settings_writes: Arc<Mutex<Vec<(String, serde_json::Value)>>>,
}

/// The presence events every `/sync` serves, and how often they changed:
/// that is part of the sync token, since the SDK skips a response whose
/// token it already has.
#[derive(Default)]
struct MockPresence {
    events: Vec<serde_json::Value>,
    changes: usize,
}

/// What the mock homeserver fails, as the network or a proxy would: a
/// failed request gets its connection closed without an answer, or held,
/// or a proxy's error page.
#[derive(Default)]
struct MockFaults {
    /// The next this many `/sync` requests fail.
    drop_syncs: AtomicUsize,
    /// Every `/send/` request fails while this is set.
    send_down: AtomicBool,
    /// Every `/login` request is held while this is set.
    hold_login: AtomicBool,
    /// Every `/logout` request is held while this is set; it still counts
    /// in `logouts`.
    hold_logout: AtomicBool,
    /// Every `/logout` request fails while this is set, as on a network
    /// that went away; it still counts in `logouts`.
    drop_logout: AtomicBool,
    /// Every `/sync` request is answered `503 Service Unavailable`, with
    /// a page of HTML, while this is set: a proxy in front of a stopped
    /// homeserver.
    sync_unavailable: AtomicBool,
    /// The server signed the session out (from another client, say):
    /// `/sync` and `/logout` answer `M_UNKNOWN_TOKEN` while this is set.
    session_ended: AtomicBool,
    /// The requests held unanswered, their connections open, while the
    /// mock goes on answering the others.
    held: Mutex<Vec<std::net::TcpStream>>,
}

impl MockBackfillHomeserver {
    /// Waits until the mock got `count` `read_markers` requests; their
    /// bodies.
    fn wait_for_read_markers(
        &self,
        count: usize,
    ) -> Result<Vec<serde_json::Value>, Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let bodies = self.read_markers.lock().expect("the read markers").clone();
            if bodies.len() >= count {
                return Ok(bodies);
            }
            if Instant::now() >= deadline {
                return Err(format!("the mock got {bodies:?}, not {count} read markers").into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
    }

    /// Waits until the mock got `count` presence `PUT`s; their bodies.
    fn wait_for_presence_puts(
        &self,
        count: usize,
    ) -> Result<Vec<serde_json::Value>, Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let bodies = self.presence_puts.lock().expect("the presence").clone();
            if bodies.len() >= count {
                return Ok(bodies);
            }
            if Instant::now() >= deadline {
                return Err(format!("the mock got {bodies:?}, not {count} presence PUTs").into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
    }

    /// Waits until a `/sync` after the first `after` says `set_presence`
    /// as `presence` (`None`: without the parameter).
    fn wait_for_sync_presence(
        &self,
        after: usize,
        presence: Option<&str>,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let syncs = self.sync_presence.lock().expect("the syncs").clone();
            if syncs[after.min(syncs.len())..]
                .iter()
                .any(|said| said.as_deref() == presence)
            {
                return Ok(());
            }
            if Instant::now() >= deadline {
                return Err(format!(
                    "no sync after the first {after} said {presence:?}: {syncs:?}"
                )
                .into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
    }

    /// The typing notices so far.
    fn typing_notices(&self) -> Vec<serde_json::Value> {
        self.typing.lock().expect("the typing notices").clone()
    }

    /// Waits until the mock got `count` typing notices; their bodies.
    fn wait_for_typing_notices(
        &self,
        count: usize,
    ) -> Result<Vec<serde_json::Value>, Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let bodies = self.typing_notices();
            if bodies.len() >= count {
                return Ok(bodies);
            }
            if Instant::now() >= deadline {
                return Err(format!("the mock got {bodies:?}, not {count} typing notices").into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
    }

    /// Waits until the mock got `count` settings writes; them.
    fn wait_for_settings_writes(
        &self,
        count: usize,
    ) -> Result<Vec<(String, serde_json::Value)>, Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let writes = self.settings_writes.lock().expect("the writes").clone();
            if writes.len() >= count {
                return Ok(writes);
            }
            if Instant::now() >= deadline {
                return Err(format!("the mock got {writes:?}, not {count} settings writes").into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
    }

    /// How many requests the mock got so far.
    fn request_count(&self) -> usize {
        self.requests.lock().expect("the requests").len()
    }

    /// The requests after the first `mark`.
    fn requests_since(&self, mark: usize) -> Vec<String> {
        self.requests.lock().expect("the requests")[mark..].to_vec()
    }

    fn sync_count(&self) -> usize {
        self.sync_presence.lock().expect("the syncs").len()
    }

    /// A new event in Beta's timeline, from the next `/sync` on.
    fn append_timeline(&self, event: serde_json::Value) {
        self.timeline.lock().expect("the timeline").push(event);
    }

    /// Beta's timeline goes empty from the next `/sync` on. Returns once the
    /// client took every sync that had the old events.
    fn clear_timeline(&self) -> Result<(), Box<dyn std::error::Error>> {
        self.timeline.lock().expect("the timeline").clear();
        self.wait_for_two_syncs()
    }

    /// Every `/sync` serves `events` as its presence from the next on.
    /// Returns once the client took them, as `clear_timeline`.
    fn serve_presence(
        &self,
        events: Vec<serde_json::Value>,
    ) -> Result<(), Box<dyn std::error::Error>> {
        self.set_presence(events);
        self.wait_for_two_syncs()
    }

    /// The same without waiting: for a client not running.
    fn set_presence(&self, events: Vec<serde_json::Value>) {
        let mut presence = self.presence.lock().expect("the presence");
        presence.events = events;
        presence.changes += 1;
    }

    /// Returns once the client asked twice from now: it took every answer
    /// before (it asks again only after it handled an answer).
    fn wait_for_two_syncs(&self) -> Result<(), Box<dyn std::error::Error>> {
        let after = self.sync_count();
        let deadline = Instant::now() + Duration::from_secs(30);
        while self.sync_count() < after + 2 {
            if Instant::now() >= deadline {
                return Err("the client stopped syncing".into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
        Ok(())
    }

    fn held(&self) -> usize {
        self.faults.held.lock().expect("the held requests").len()
    }

    fn wait_for_held(&self, count: usize) -> Result<(), Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(30);
        while self.held() < count {
            if Instant::now() >= deadline {
                return Err(format!("the mock holds {} requests, not {count}", self.held()).into());
            }
            std::thread::sleep(POLL_INTERVAL);
        }
        Ok(())
    }

    /// Answers every held request with `body`: the held `/messages`.
    fn answer_held_messages(&self, body: &serde_json::Value) {
        for mut stream in self
            .faults
            .held
            .lock()
            .expect("the held requests")
            .drain(..)
        {
            respond_json(&mut stream, 200, body);
        }
    }
}

/// How the mock homeserver answers `/messages` history requests.
enum MockMessages {
    /// Hold every request unanswered (see `MockFaults::held`) until the
    /// test answers it.
    Hang,
    /// Answer every request with this response body.
    Respond(serde_json::Value),
}

fn spawn_mock_backfill_homeserver() -> Result<MockBackfillHomeserver, Box<dyn std::error::Error>> {
    spawn_mock_homeserver(MockMessages::Hang, vec![])
}

/// How the mock homeserver signs users in.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MockAuth {
    /// `/login` answers every request with a session of Alice's: device
    /// `DEVICE` the first time, then `DEVICE2`, `DEVICE3`...
    Password,
    /// An OAuth 2.0 authorization server on the same port, as MAS behind a
    /// homeserver: it registers `mirx-client` and grants `oauth-token`.
    /// The test plays the browser, so `/oauth2/authorize` is not served.
    OAuth,
}

/// Serves `!beta:example` with Alice and Bob in the sync `state` section and
/// `timeline_events` as its sync timeline. Every `/sync` gets the same body,
/// until the test appends to the timeline.
/// The `/members` list also has the members that join in the timeline.
fn spawn_mock_homeserver(
    messages: MockMessages,
    timeline_events: Vec<serde_json::Value>,
) -> Result<MockBackfillHomeserver, Box<dyn std::error::Error>> {
    spawn_mock_homeserver_with_auth(MockAuth::Password, messages, timeline_events, None)
}

/// `spawn_mock_homeserver` whose `!beta:example` has its read marker
/// (`m.fully_read` room account data) on `fully_read`. Every sync says so:
/// a marker the client moves never comes back moved.
fn spawn_mock_homeserver_with_read_marker(
    timeline_events: Vec<serde_json::Value>,
    fully_read: &str,
) -> Result<MockBackfillHomeserver, Box<dyn std::error::Error>> {
    spawn_mock_homeserver_with_auth(
        MockAuth::Password,
        MockMessages::Hang,
        timeline_events,
        Some(fully_read.to_owned()),
    )
}

fn spawn_mock_homeserver_with_auth(
    auth: MockAuth,
    messages: MockMessages,
    timeline_events: Vec<serde_json::Value>,
    fully_read: Option<String>,
) -> Result<MockBackfillHomeserver, Box<dyn std::error::Error>> {
    let listener = TcpListener::bind("127.0.0.1:0")?;
    let address = listener.local_addr()?;
    let issuer = format!("http://{address}/");
    let faults = Arc::new(MockFaults::default());
    let mock_faults = Arc::clone(&faults);
    let read_markers = Arc::new(Mutex::new(Vec::new()));
    let mock_read_markers = Arc::clone(&read_markers);
    let timeline = Arc::new(Mutex::new(timeline_events.clone()));
    let mock_timeline = Arc::clone(&timeline);
    let presence_puts = Arc::new(Mutex::new(Vec::<serde_json::Value>::new()));
    let mock_presence_puts = Arc::clone(&presence_puts);
    let sync_presence = Arc::new(Mutex::new(Vec::new()));
    let mock_sync_presence = Arc::clone(&sync_presence);
    let typing = Arc::new(Mutex::new(Vec::<serde_json::Value>::new()));
    let mock_typing = Arc::clone(&typing);
    let logouts = Arc::new(AtomicUsize::new(0));
    let mock_logouts = Arc::clone(&logouts);
    let presence = Arc::new(Mutex::new(MockPresence::default()));
    let mock_presence = Arc::clone(&presence);
    let requests = Arc::new(Mutex::new(Vec::new()));
    let mock_requests = Arc::clone(&requests);
    let settings_writes = Arc::new(Mutex::new(Vec::new()));
    let mock_settings_writes = Arc::clone(&settings_writes);
    let room_account_data = fully_read
        .into_iter()
        .map(|event_id| {
            serde_json::json!({
                "type": "m.fully_read",
                "content": { "event_id": event_id }
            })
        })
        .collect::<Vec<_>>();
    std::thread::spawn(move || {
        let alice_member = serde_json::json!({
            "content": {
                "membership": "join",
                "displayname": "Alice"
            },
            "event_id": "$member",
            "origin_server_ts": 1700000000001u64,
            "sender": "@alice:example",
            "state_key": "@alice:example",
            "type": "m.room.member"
        });
        let bob_member = serde_json::json!({
            "content": {
                "membership": "join",
                "displayname": "Bob"
            },
            "event_id": "$bob-member",
            "origin_server_ts": 1700000000004u64,
            "sender": "@bob:example",
            "state_key": "@bob:example",
            "type": "m.room.member"
        });
        let members = [alice_member.clone(), bob_member.clone()]
            .into_iter()
            .chain(
                timeline_events
                    .iter()
                    .filter(|event| event["type"] == "m.room.member")
                    .cloned(),
            )
            .collect::<Vec<_>>();
        // The sign-ins answered so far; each makes a new device.
        let mut logins = 0usize;
        for mut stream in listener.incoming().flatten() {
            let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
            let mut request = Vec::new();
            let mut buffer = [0u8; 4096];
            while let Ok(read) = stream.read(&mut buffer) {
                if read == 0 {
                    break;
                }
                request.extend_from_slice(&buffer[..read]);
                if request.windows(4).any(|window| window == b"\r\n\r\n") {
                    break;
                }
            }

            // Read the body too: closing with unread bytes resets the
            // connection before the client reads the response.
            let header_end = request
                .windows(4)
                .position(|window| window == b"\r\n\r\n")
                .map_or(request.len(), |position| position + 4);
            let content_length = String::from_utf8_lossy(&request[..header_end])
                .lines()
                .find_map(|line| {
                    let (name, value) = line.split_once(':')?;
                    name.eq_ignore_ascii_case("content-length")
                        .then(|| value.trim().parse::<usize>().ok())?
                })
                .unwrap_or(0);
            while request.len() < header_end + content_length {
                match stream.read(&mut buffer) {
                    Ok(0) | Err(_) => break,
                    Ok(read) => request.extend_from_slice(&buffer[..read]),
                }
            }

            let request = String::from_utf8_lossy(&request);
            let request_line = request.lines().next().unwrap_or_default();
            let path = request_line.split_whitespace().nth(1).unwrap_or("/");
            mock_requests.lock().expect("the requests").push(format!(
                "{} {}",
                request_line.split_whitespace().next().unwrap_or_default(),
                path.split_once('?').map_or(path, |(path, _)| path)
            ));

            // The request was read: closing now is a connection the
            // network dropped, not a reset of unread bytes.
            let dropped_sync = path.contains("/sync")
                && mock_faults
                    .drop_syncs
                    .try_update(Ordering::SeqCst, Ordering::SeqCst, |count| {
                        count.checked_sub(1)
                    })
                    .is_ok();
            let dropped_send =
                path.contains("/send/") && mock_faults.send_down.load(Ordering::SeqCst);
            if dropped_sync || dropped_send {
                continue;
            }
            if path == "/_matrix/client/v3/logout" {
                mock_logouts.fetch_add(1, Ordering::SeqCst);
                if mock_faults.hold_logout.load(Ordering::SeqCst) {
                    mock_faults
                        .held
                        .lock()
                        .expect("the held requests")
                        .push(stream);
                    continue;
                }
                if mock_faults.drop_logout.load(Ordering::SeqCst) {
                    continue;
                }
            }
            if path.contains("/sync") && mock_faults.sync_unavailable.load(Ordering::SeqCst) {
                respond_proxy_error(&mut stream);
                continue;
            }
            if mock_faults.session_ended.load(Ordering::SeqCst)
                && (path.contains("/sync") || path == "/_matrix/client/v3/logout")
            {
                respond_json(
                    &mut stream,
                    401,
                    &serde_json::json!({
                        "errcode": "M_UNKNOWN_TOKEN",
                        "error": "Invalid token",
                        "soft_logout": false
                    }),
                );
                continue;
            }

            if auth == MockAuth::OAuth {
                let body = match path {
                    // The versions below 1.15 pick the unstable path.
                    "/_matrix/client/unstable/org.matrix.msc2965/auth_metadata" => {
                        Some(serde_json::json!({
                            "issuer": issuer,
                            "authorization_endpoint": format!("{issuer}oauth2/authorize"),
                            "token_endpoint": format!("{issuer}oauth2/token"),
                            "registration_endpoint": format!("{issuer}oauth2/registration"),
                            "revocation_endpoint": format!("{issuer}oauth2/revoke"),
                            "response_types_supported": ["code"],
                            "response_modes_supported": ["query", "fragment"],
                            "grant_types_supported": ["authorization_code", "refresh_token"],
                            "code_challenge_methods_supported": ["S256"],
                            "prompt_values_supported": ["create"],
                        }))
                    }
                    "/oauth2/registration" => Some(serde_json::json!({
                        "client_id": "mirx-client",
                    })),
                    "/oauth2/token" => Some(serde_json::json!({
                        "access_token": "oauth-token",
                        "token_type": "Bearer",
                        "expires_in": 3600,
                        "refresh_token": "oauth-refresh",
                    })),
                    "/_matrix/client/v3/account/whoami" => Some(serde_json::json!({
                        "user_id": "@alice:example",
                    })),
                    _ => None,
                };
                if let Some(body) = body {
                    respond_json(&mut stream, 200, &body);
                    continue;
                }
            }

            if path == "/_matrix/client/v3/login" {
                if mock_faults.hold_login.load(Ordering::SeqCst) {
                    mock_faults
                        .held
                        .lock()
                        .expect("the held requests")
                        .push(stream);
                    continue;
                }
                logins += 1;
                let device_id = match logins {
                    1 => "DEVICE".to_owned(),
                    n => format!("DEVICE{n}"),
                };
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "user_id": "@alice:example",
                        "access_token": "secret-token",
                        "device_id": device_id
                    }),
                );
                continue;
            }

            if path == "/_matrix/client/v3/logout" {
                respond_json(&mut stream, 200, &serde_json::json!({}));
                continue;
            }

            if path == "/_matrix/client/versions" {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "versions": ["r0.6.1", "v1.1"]
                    }),
                );
                continue;
            }

            if path.contains("/sync") {
                mock_sync_presence.lock().expect("the syncs").push(
                    path.split_once('?')
                        .and_then(|(_, query)| {
                            query
                                .split('&')
                                .find_map(|pair| pair.strip_prefix("set_presence="))
                        })
                        .map(str::to_owned),
                );
                // A continuous sync loop polls with `since`; idle like a
                // long-poll instead of spinning.
                if path.contains("since=") {
                    std::thread::sleep(Duration::from_millis(500));
                }
                let timeline = mock_timeline.lock().expect("the timeline").clone();
                let (presence, presence_changes) = {
                    let presence = mock_presence.lock().expect("the presence");
                    (presence.events.clone(), presence.changes)
                };
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        // A new token for every timeline and presence.
                        "next_batch": format!("s-sync-{}-{presence_changes}", timeline.len()),
                        "presence": { "events": presence },
                        "device_one_time_keys_count": {
                            "signed_curve25519": 0
                        },
                        "device_lists": {
                            "changed": [],
                            "left": []
                        },
                        "rooms": {
                            "join": {
                                "!beta:example": {
                                    "summary": {
                                        "m.joined_member_count": 2,
                                        "m.invited_member_count": 0
                                    },
                                    "state": {
                                        "events": [
                                            {
                                                "content": {
                                                    "creator": "@alice:example",
                                                    "room_version": "10"
                                                },
                                                "event_id": "$create",
                                                "origin_server_ts": 1700000000000u64,
                                                "sender": "@alice:example",
                                                "state_key": "",
                                                "type": "m.room.create"
                                            },
                                            alice_member,
                                            bob_member,
                                            beta_power_levels(),
                                            {
                                                "content": {
                                                    "name": "Beta"
                                                },
                                                "event_id": "$name",
                                                "origin_server_ts": 1700000000002u64,
                                                "sender": "@alice:example",
                                                "state_key": "",
                                                "type": "m.room.name"
                                            }
                                        ]
                                    },
                                    "timeline": {
                                        "events": timeline,
                                        "limited": false,
                                        "prev_batch": "s-current"
                                    },
                                    "ephemeral": {
                                        "events": []
                                    },
                                    "account_data": {
                                        "events": room_account_data
                                    },
                                    "unread_notifications": {
                                        "notification_count": 0,
                                        "highlight_count": 0
                                    }
                                }
                            }
                        }
                    }),
                );
                continue;
            }

            // Bob's profile, for a whois; the SDK sends `@` and `:`
            // unencoded.
            if path == "/_matrix/client/v3/profile/@bob:example" {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({ "displayname": "Bob" }),
                );
                continue;
            }

            // The user's presence: as Synapse, a GET reads what the last
            // PUT set.
            if path.starts_with("/_matrix/client/v3/presence/") && path.ends_with("/status") {
                let mut puts = mock_presence_puts.lock().expect("the presence");
                if request_line.starts_with("PUT ") {
                    let body = &request[request
                        .find("\r\n\r\n")
                        .map_or(request.len(), |end| end + 4)..];
                    puts.push(serde_json::from_str(body).expect("a presence JSON body"));
                    respond_json(&mut stream, 200, &serde_json::json!({}));
                } else {
                    let presence = puts
                        .last()
                        .map_or(serde_json::json!("online"), |put| put["presence"].clone());
                    respond_json(
                        &mut stream,
                        200,
                        &serde_json::json!({ "presence": presence }),
                    );
                }
                continue;
            }

            // A typing notice, in any room: every test that types in a
            // connected window sends them.
            if path.starts_with("/_matrix/client/v3/rooms/!") && path.contains("/typing/") {
                let body = &request[request
                    .find("\r\n\r\n")
                    .map_or(request.len(), |end| end + 4)..];
                mock_typing
                    .lock()
                    .expect("the typing notices")
                    .push(serde_json::from_str(body).expect("a typing JSON body"));
                respond_json(&mut stream, 200, &serde_json::json!({}));
                continue;
            }

            // The read receipt and the read marker; the sync body never
            // echoes them.
            if path.ends_with("/read_markers") {
                let body = &request[request
                    .find("\r\n\r\n")
                    .map_or(request.len(), |end| end + 4)..];
                mock_read_markers
                    .lock()
                    .expect("the read markers")
                    .push(serde_json::from_str(body).expect("a read_markers JSON body"));
                respond_json(&mut stream, 200, &serde_json::json!({}));
                continue;
            }

            if path.contains("/room_keys/version") {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "algorithm": "m.megolm_backup.v1.curve25519-aes-sha2",
                        "auth_data": {
                            "public_key": "AQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQE"
                        },
                        "count": 0,
                        "etag": "1",
                        "version": "1"
                    }),
                );
                continue;
            }

            if path.contains("/keys/upload") {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "one_time_key_counts": {}
                    }),
                );
                continue;
            }

            if path.contains("/keys/query") {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "device_keys": {},
                        "failures": {},
                        "master_keys": {},
                        "self_signing_keys": {},
                        "user_signing_keys": {}
                    }),
                );
                continue;
            }

            if path.contains("/account_data/m.secret_storage.default_key") {
                respond_json(
                    &mut stream,
                    404,
                    &serde_json::json!({
                        "errcode": "M_NOT_FOUND",
                        "error": "not found"
                    }),
                );
                continue;
            }

            // Beta's settings, for Channel Central: its whole state, its
            // power levels, its directory listing, and the writes to them,
            // which answer as accepted and change nothing served.
            let method = request_line.split_whitespace().next().unwrap_or_default();
            let unencoded = path
                .split_once('?')
                .map_or(path, |(path, _)| path)
                .replace("%21beta%3Aexample", "!beta:example");
            let body = || -> serde_json::Value {
                let body = &request[request
                    .find("\r\n\r\n")
                    .map_or(request.len(), |end| end + 4)..];
                serde_json::from_str(body).expect("a settings JSON body")
            };
            if let Some(rest) = unencoded.strip_prefix("/_matrix/client/v3/rooms/!beta:example/") {
                let answer = match (method, rest) {
                    ("GET", "state") => Some(serde_json::json!(beta_settings_state())),
                    ("GET", "state/m.room.power_levels/") => {
                        Some(beta_power_levels()["content"].clone())
                    }
                    ("PUT", rest) if rest.starts_with("state/m.room.") => {
                        let mut writes = mock_settings_writes.lock().expect("the writes");
                        writes.push((format!("PUT {rest}"), body()));
                        Some(
                            serde_json::json!({ "event_id": format!("$setting-{}", writes.len()) }),
                        )
                    }
                    ("POST", "unban") => {
                        mock_settings_writes
                            .lock()
                            .expect("the writes")
                            .push(("POST unban".to_owned(), body()));
                        Some(serde_json::json!({}))
                    }
                    _ => None,
                };
                if let Some(answer) = answer {
                    respond_json(&mut stream, 200, &answer);
                    continue;
                }
            }
            if unencoded == "/_matrix/client/v3/directory/list/room/!beta:example" {
                if method == "PUT" {
                    mock_settings_writes
                        .lock()
                        .expect("the writes")
                        .push(("PUT directory".to_owned(), body()));
                    respond_json(&mut stream, 200, &serde_json::json!({}));
                } else {
                    respond_json(
                        &mut stream,
                        200,
                        &serde_json::json!({ "visibility": "private" }),
                    );
                }
                continue;
            }

            if path.contains("/rooms/!beta:example/state/m.room.encryption/")
                || path.contains("/rooms/%21beta%3Aexample/state/m.room.encryption/")
            {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "content": {
                            "algorithm": "m.megolm.v1.aes-sha2"
                        },
                        "event_id": "$encryption",
                        "origin_server_ts": 1700000000003u64,
                        "sender": "@alice:example",
                        "state_key": "",
                        "type": "m.room.encryption"
                    }),
                );
                continue;
            }

            // `/join #name:example` (the SDK percent-encodes `#`) joins
            // `!name:example`. The room has no state yet; the snapshot after
            // the join reads its encryption state.
            if let Some(name) = path
                .strip_prefix("/_matrix/client/v3/join/%23")
                .and_then(|alias| alias.strip_suffix(":example"))
            {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({ "room_id": format!("!{name}:example") }),
                );
                continue;
            }
            if path.starts_with("/_matrix/client/v3/rooms/!")
                && path.ends_with(":example/state/m.room.encryption/")
            {
                respond_json(
                    &mut stream,
                    404,
                    &serde_json::json!({ "errcode": "M_NOT_FOUND", "error": "not found" }),
                );
                continue;
            }

            // A send is `$sent-<transaction>`; the sync body never echoes
            // it.
            if let Some(transaction_id) = path
                .strip_prefix("/_matrix/client/v3/rooms/!")
                .filter(|rest| rest.contains(":example/send/"))
                .and_then(|rest| rest.rsplit('/').next())
            {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({ "event_id": format!("$sent-{transaction_id}") }),
                );
                continue;
            }

            // `/create` makes `!created:example`.
            if path == "/_matrix/client/v3/createRoom" {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({ "room_id": "!created:example" }),
                );
                continue;
            }

            // The room directory, in two pages.
            if path == "/_matrix/client/v3/publicRooms" {
                let page = if request.contains("\"since\":\"page2\"") {
                    serde_json::json!({
                        "chunk": [
                            public_room_chunk("!zed:example", Some("#zed:example"), "Zed", 40),
                            public_room_chunk("!alpha:example", Some("#alpha:example"), "Alpha", 1),
                        ],
                        "total_room_count_estimate": 5
                    })
                } else {
                    serde_json::json!({
                        "chunk": [
                            public_room_chunk("!rust:example", Some("#rust:example"), "Rust", 120),
                            public_room_chunk("!beta:example", Some("#beta:example"), "Beta", 2),
                            public_room_chunk("!opaque:example", None, "Opaque", 7),
                        ],
                        "next_batch": "page2",
                        "total_room_count_estimate": 5
                    })
                };
                respond_json(&mut stream, 200, &page);
                continue;
            }

            if path.contains("/rooms/%21beta%3Aexample/members")
                || path.contains("/rooms/!beta:example/members")
            {
                respond_json(&mut stream, 200, &serde_json::json!({ "chunk": members }));
                continue;
            }

            // Another, which its sender edited: the server bundles the
            // edit.
            if path == "/_matrix/client/v3/rooms/!beta:example/event/$old-edited" {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "content": { "msgtype": "m.text", "body": "from the archive" },
                        "event_id": "$old-edited",
                        "origin_server_ts": 1690000000000u64,
                        "room_id": "!beta:example",
                        "sender": "@alice:example",
                        "type": "m.room.message",
                        "unsigned": { "m.relations": { "m.replace": {
                            "content": {
                                "msgtype": "m.text",
                                "body": "* from the archive, corrected",
                                "m.new_content": {
                                    "msgtype": "m.text",
                                    "body": "from the archive, corrected"
                                },
                                "m.relates_to": { "rel_type": "m.replace", "event_id": "$old-edited" }
                            },
                            "event_id": "$old-correction",
                            "origin_server_ts": 1690000060000u64,
                            "room_id": "!beta:example",
                            "sender": "@alice:example",
                            "type": "m.room.message"
                        }}}
                    }),
                );
                continue;
            }

            // A message replied to in the timeline but not part of it. The
            // SDK sends `!`, `:` and `$` in the path unencoded.
            if path == "/_matrix/client/v3/rooms/!beta:example/event/$old" {
                respond_json(
                    &mut stream,
                    200,
                    &serde_json::json!({
                        "content": { "msgtype": "m.text", "body": "from the archive" },
                        "event_id": "$old",
                        "origin_server_ts": 1690000000000u64,
                        "room_id": "!beta:example",
                        "sender": "@alice:example",
                        "type": "m.room.message"
                    }),
                );
                continue;
            }

            if path.contains("/rooms/%21beta%3Aexample/messages")
                || path.contains("/rooms/!beta:example/messages")
            {
                match &messages {
                    MockMessages::Hang => {
                        mock_faults
                            .held
                            .lock()
                            .expect("the held requests")
                            .push(stream);
                    }
                    MockMessages::Respond(body) => respond_json(&mut stream, 200, body),
                }
                continue;
            }

            // The sticker of `bob_sticker_and_poll`.
            if path.contains("/media/") && path.contains("/example/sticker") {
                respond_png(&mut stream);
                continue;
            }

            respond_json(
                &mut stream,
                404,
                &serde_json::json!({
                    "errcode": "M_UNRECOGNIZED",
                    "error": format!("unhandled mock homeserver path: {path}")
                }),
            );
        }
    });

    Ok(MockBackfillHomeserver {
        base_url: format!("http://{address}"),
        faults,
        read_markers,
        timeline,
        presence_puts,
        sync_presence,
        typing,
        logouts,
        presence,
        requests,
        settings_writes,
    })
}

/// Beta's power levels, as every `/sync` serves them: Alice 100, Bob 50.
fn beta_power_levels() -> serde_json::Value {
    serde_json::json!({
        "content": {
            "users": {
                "@alice:example": 100,
                "@bob:example": 50
            }
        },
        "event_id": "$power",
        "origin_server_ts": 1700000000005u64,
        "sender": "@alice:example",
        "state_key": "",
        "type": "m.room.power_levels"
    })
}

/// Beta's whole current state, as `GET /rooms/{id}/state` answers it:
/// the sync's, and an invite-only join rule, a topic and Carol banned by
/// Alice.
fn beta_settings_state() -> Vec<serde_json::Value> {
    let state = |event_type: &str, state_key: &str, sender: &str, content: serde_json::Value| {
        serde_json::json!({
            "content": content,
            "event_id": format!("${event_type}-{state_key}"),
            "origin_server_ts": 1700000000000u64,
            "room_id": "!beta:example",
            "sender": sender,
            "state_key": state_key,
            "type": event_type
        })
    };
    let mut power_levels = beta_power_levels();
    power_levels["room_id"] = serde_json::json!("!beta:example");
    vec![
        state(
            "m.room.create",
            "",
            "@alice:example",
            serde_json::json!({ "creator": "@alice:example", "room_version": "10" }),
        ),
        state(
            "m.room.member",
            "@alice:example",
            "@alice:example",
            serde_json::json!({ "membership": "join", "displayname": "Alice" }),
        ),
        state(
            "m.room.member",
            "@bob:example",
            "@bob:example",
            serde_json::json!({ "membership": "join", "displayname": "Bob" }),
        ),
        power_levels,
        state(
            "m.room.name",
            "",
            "@alice:example",
            serde_json::json!({ "name": "Beta" }),
        ),
        state(
            "m.room.topic",
            "",
            "@alice:example",
            serde_json::json!({ "topic": "Beta's topic" }),
        ),
        state(
            "m.room.join_rules",
            "",
            "@alice:example",
            serde_json::json!({ "join_rule": "invite" }),
        ),
        state(
            "m.room.member",
            "@carol:example",
            "@alice:example",
            serde_json::json!({ "membership": "ban", "reason": "spam" }),
        ),
    ]
}

/// A room directory entry whose topic is "About {name}".
fn public_room_chunk(
    room_id: &str,
    alias: Option<&str>,
    name: &str,
    joined_members: u64,
) -> serde_json::Value {
    let mut chunk = serde_json::json!({
        "room_id": room_id,
        "name": name,
        "topic": format!("About {name}"),
        "num_joined_members": joined_members,
        "world_readable": false,
        "guest_can_join": false
    });
    if let Some(alias) = alias {
        chunk["canonical_alias"] = serde_json::json!(alias);
    }
    chunk
}

/// A 1x1 PNG.
fn respond_png(stream: &mut std::net::TcpStream) {
    let body: &[u8] = &[
        137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13, 73, 72, 68, 82, 0, 0, 0, 1, 0, 0, 0, 1, 8, 4,
        0, 0, 0, 181, 28, 12, 2, 0, 0, 0, 11, 73, 68, 65, 84, 120, 218, 99, 252, 255, 31, 0, 3, 3,
        2, 0, 239, 191, 107, 212, 0, 0, 0, 0, 73, 69, 78, 68, 174, 66, 96, 130,
    ];
    let response = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: image/png\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    let _ = stream.write_all(response.as_bytes());
    let _ = stream.write_all(body);
}

fn respond_json(stream: &mut std::net::TcpStream, status: u16, body: &serde_json::Value) {
    let reason = match status {
        200 => "OK",
        404 => "Not Found",
        _ => "Error",
    };
    let body = serde_json::to_vec(body).expect("mock homeserver response must serialize");
    let response = format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    let _ = stream.write_all(response.as_bytes());
    let _ = stream.write_all(&body);
}

/// A reverse proxy's answer while the homeserver behind it is down.
fn respond_proxy_error(stream: &mut std::net::TcpStream) {
    let body = "<html>503</html>";
    let response = format!(
        "HTTP/1.1 503 Service Unavailable\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    let _ = stream.write_all(response.as_bytes());
}

