/// Windows ending the session ends mirx as Exit does, and the marker has
/// reached the server before mirx answers: Windows may end the process
/// once it has.
#[test]
fn automation_driver_the_session_ending_moves_the_marker_before_it_answers()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, server, local_app_data) = launch_in_beta_with_its_marker_seen()?;
    let frame = app.automation_frame_hwnd() as HWND;

    let mut result = 0;
    assert_ne!(
        unsafe {
            SendMessageTimeoutW(
                frame,
                WM_ENDSESSION,
                1,
                ENDSESSION_LOGOFF as isize,
                SMTO_NORMAL,
                10_000,
                &mut result,
            )
        },
        0
    );
    assert_eq!(unsafe { IsWindow(frame) }, 0);
    assert_eq!(
        server.read_markers.lock().unwrap()[1..],
        [serde_json::json!({ "m.fully_read": "$bob-4" })]
    );
    assert!(
        app.end(|app| app.wait_for_exit(Duration::from_secs(30)))?
            .success()
    );

    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// The server counts a sticker and a poll unread, so they are lines: the
/// receipt and the read marker reach the poll's end.
#[test]
fn automation_driver_a_sticker_and_a_poll_are_read_lines() -> Result<(), Box<dyn std::error::Error>>
{
    let local_app_data = unique_local_app_data_path();
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let mut timeline = bob_lines(4);
    timeline.extend(bob_sticker_and_poll());
    let server = spawn_mock_homeserver_with_read_marker(timeline, "$bob-2")?;
    write_saved_session(&local_app_data, &server.base_url)?;
    let app = launch_app_with_options(
        &exe_path,
        &[OsString::from("--automation")],
        launch_options(Some(local_app_data.clone())),
    )?;
    app.wait_for_connection("syncing", Duration::from_secs(30))?;
    let lines = wait_for_line_marker(&app)?;
    let tail = lines
        .iter()
        .rev()
        .take(3)
        .rev()
        .map(|line| {
            line.split_once("] ")
                .map_or(line.as_str(), |(_, text)| text)
        })
        .collect::<Vec<_>>();
    assert_eq!(
        tail,
        [
            "* Bob sent sticker: a waving cat",
            "* Bob started a poll: Lunch? 1) Pizza 2) Sushi",
            "* Bob ended the poll \"Lunch?\": The poll has ended. Top answer: Pizza",
        ],
        "{lines:?}"
    );

    app.select_navigation_view(&room_identity("!beta:example"))?;
    assert_eq!(
        server.wait_for_read_markers(1)?,
        [serde_json::json!({ "m.read": "$poll-end" })]
    );
    app.select_navigation_view(&ViewIdentity::Status)?;
    assert_eq!(
        server.wait_for_read_markers(2)?[1..],
        [serde_json::json!({ "m.fully_read": "$poll-end" })]
    );
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(server.read_markers.lock().unwrap().len(), 2);
    assert_eq!(app.dump_model()?.last_error, None);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// While mirx is in front, the active window's new lines are read: each
/// gets its receipt once, though the server never echoes it.
#[test]
fn automation_driver_active_window_reads_new_lines() -> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let server = spawn_mock_homeserver_with_read_marker(bob_lines(4), "$bob-2")?;
    write_saved_session(&local_app_data, &server.base_url)?;
    let app = launch_app_with_options(
        &exe_path,
        &[OsString::from("--automation")],
        launch_options(Some(local_app_data.clone())),
    )?;
    app.wait_for_connection("syncing", Duration::from_secs(30))?;
    wait_for_line_marker(&app)?;
    app.select_navigation_view(&room_identity("!beta:example"))?;
    unsafe { SetForegroundWindow(app.automation_frame_hwnd() as HWND) };
    assert_eq!(
        server.wait_for_read_markers(1)?,
        [serde_json::json!({ "m.read": "$bob-4" })]
    );

    server.append_timeline(bob_lines(5).pop().expect("Bob's fifth line"));
    assert_eq!(
        server.wait_for_read_markers(2)?[1..],
        [serde_json::json!({ "m.read": "$bob-5" })]
    );
    // Every sync serves the line again; it was read once.
    std::thread::sleep(Duration::from_secs(2));
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(server.read_markers.lock().unwrap().len(), 2);
    assert_eq!(app.dump_model()?.last_error, None);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Sends `window` `WM_SYSCOMMAND command`, as its caption buttons do. Sent,
/// so it has run on return.
fn send_syscommand(window: HWND, command: u32) {
    let mut result = 0;
    assert_ne!(
        unsafe {
            SendMessageTimeoutW(
                window,
                WM_SYSCOMMAND,
                command as WPARAM,
                0,
                SMTO_NORMAL,
                5_000,
                &mut result,
            )
        },
        0
    );
}

/// Minimizing mirx leaves the active window: its read marker moves, the
/// rule having been on screen. Restoring it enters the window again.
#[test]
fn automation_driver_minimizing_mirx_moves_the_read_marker()
-> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let server = spawn_mock_homeserver_with_read_marker(bob_lines(4), "$bob-2")?;
    write_saved_session(&local_app_data, &server.base_url)?;
    let app = launch_app_with_options(
        &exe_path,
        &[OsString::from("--automation")],
        launch_options(Some(local_app_data.clone())),
    )?;
    app.wait_for_connection("syncing", Duration::from_secs(30))?;
    wait_for_line_marker(&app)?;
    let beta = room_identity("!beta:example");
    app.select_navigation_view(&beta)?;
    assert_eq!(
        server.wait_for_read_markers(1)?,
        [serde_json::json!({ "m.read": "$bob-4" })]
    );
    app.wait_idle(Duration::from_secs(5))?;

    let frame = app.automation_frame_hwnd() as HWND;
    send_syscommand(frame, SC_MINIMIZE);
    assert_eq!(
        server.wait_for_read_markers(2)?[1..],
        [serde_json::json!({ "m.fully_read": "$bob-4" })]
    );
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(app.dump_ui_state()?.mdi.active, beta);
    // Minimized, it is left already.
    send_syscommand(frame, SC_MINIMIZE);
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(server.read_markers.lock().unwrap().len(), 2);

    // Back, the rule (the marker never echoed) is on screen again, and
    // leaving moves the marker again.
    send_syscommand(frame, SC_RESTORE);
    app.wait_idle(Duration::from_secs(5))?;
    std::thread::sleep(Duration::from_millis(500));
    send_syscommand(frame, SC_MINIMIZE);
    assert_eq!(
        server.wait_for_read_markers(3)?[2..],
        [serde_json::json!({ "m.fully_read": "$bob-4" })]
    );
    assert_eq!(app.dump_model()?.last_error, None);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

