/// An `--automation` app with a channel (Beta), a query with @alice
/// (Alpha) and an invite (Lobby), for the window close lifecycle.
fn launch_close_lifecycle_app() -> Result<(GuiTestApp, PathBuf), Box<dyn std::error::Error>> {
    launch_close_lifecycle_app_in(unique_local_app_data_path())
}

/// `launch_close_lifecycle_app` with the app data of an earlier run.
fn launch_close_lifecycle_app_in(
    local_app_data: PathBuf,
) -> Result<(GuiTestApp, PathBuf), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let app = launch_app_with_options(
        &exe_path,
        &[OsString::from("--automation")],
        launch_options(Some(local_app_data.clone())),
    )?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&close_lifecycle_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    Ok((app, local_app_data))
}

fn close_lifecycle_rooms() -> Vec<RoomSummary> {
    let mut alpha = room_summary("!alpha:example", "Alpha", false);
    alpha.is_direct = true;
    alpha.direct_user_ids = vec!["@alice:example".to_owned()];
    vec![
        room_summary("!beta:example", "Beta", false),
        alpha,
        invited_room_summary("!invite:example", "Lobby", false),
    ]
}

fn close_lifecycle_events() -> Vec<Event> {
    vec![
        Event::Started,
        Event::SyncedRooms(close_lifecycle_rooms()),
        text_event(
            "!beta:example",
            "@bob:example",
            1_700_000_000_000,
            "beta first",
        ),
        text_event(
            "!alpha:example",
            "@alice:example",
            1_700_000_060_000,
            "alpha first",
        ),
    ]
}

fn view_child_hwnd(
    app: &MirxApp,
    identity: &ViewIdentity,
) -> Result<HWND, Box<dyn std::error::Error>> {
    let title = find_view(&app.dump_ui_state()?, identity).title.clone();
    Ok(unsafe { mdi_child_hwnd_by_title(app, &title) })
}

/// Asks the view's MDI child to close the way its caption X does, for a
/// close that asks first. Posted, not sent: the confirmation box runs a
/// modal loop inside the handler.
fn request_view_close(
    app: &MirxApp,
    identity: &ViewIdentity,
) -> Result<HWND, Box<dyn std::error::Error>> {
    let child = view_child_hwnd(app, identity)?;
    assert_ne!(
        unsafe { PostMessageW(child, WM_SYSCOMMAND, SC_CLOSE as WPARAM, 0) },
        0,
        "posting SC_CLOSE must succeed"
    );
    Ok(child)
}

/// Closes the view's MDI child the way its caption X does, for a close
/// that must not ask: the send returns only once the close is handled,
/// and times out if a modal box blocks it.
fn close_view_without_prompt(
    app: &MirxApp,
    identity: &ViewIdentity,
) -> Result<HWND, Box<dyn std::error::Error>> {
    let child = view_child_hwnd(app, identity)?;
    let mut result = 0;
    assert_ne!(
        unsafe {
            SendMessageTimeoutW(
                child,
                WM_SYSCOMMAND,
                SC_CLOSE as WPARAM,
                0,
                SMTO_NORMAL,
                5_000,
                &mut result,
            )
        },
        0,
        "closing the view must not block on a prompt"
    );
    app.wait_idle(Duration::from_secs(5))?;
    Ok(child)
}

/// The dialog box (MessageBox or common dialog) `owner` shows, if any.
unsafe fn owned_message_box(owner: HWND) -> HWND {
    let thread_id = unsafe { GetWindowThreadProcessId(owner, std::ptr::null_mut()) };
    let mut search = (owner, 0 as HWND);
    unsafe {
        EnumThreadWindows(
            thread_id,
            Some(find_owned_message_box),
            (&raw mut search) as isize,
        );
    }
    search.1
}

unsafe extern "system" fn find_owned_message_box(hwnd: HWND, lparam: isize) -> i32 {
    let search = unsafe { &mut *(lparam as *mut (HWND, HWND)) };
    if unsafe { class_name(hwnd) } == "#32770" && unsafe { GetWindow(hwnd, GW_OWNER) } == search.0 {
        search.1 = hwnd;
        0
    } else {
        1
    }
}

/// Waits for the frame's MessageBox and returns it with its text.
fn wait_for_message_box(app: &MirxApp) -> (HWND, String) {
    wait_for_owned_message_box(app.automation_frame_hwnd() as HWND)
}

/// Waits for the MessageBox `owner` shows and returns it with its text.
fn wait_for_owned_message_box(owner: HWND) -> (HWND, String) {
    let (dialog, _) = wait_for_owned_dialog(owner);
    // MessageBox's text is the static control with ID 0xFFFF.
    let text = unsafe { read_window_text(GetDlgItem(dialog, 0xFFFF)) };
    (dialog, text)
}

/// Waits for the dialog box (`#32770`: a MessageBox or a common dialog)
/// `owner` shows and returns it with its caption.
fn wait_for_owned_dialog(owner: HWND) -> (HWND, String) {
    // The file dialog loads the shell first, so it can take a while.
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let dialog = unsafe { owned_message_box(owner) };
        // The box exists before WM_INITDIALOG fills it; a dialog box shows
        // only once that is done.
        if !dialog.is_null() && unsafe { IsWindowVisible(dialog) } != 0 {
            return (dialog, unsafe { read_window_text(dialog) });
        }
        assert!(
            Instant::now() < deadline,
            "dialog box did not appear within ten seconds"
        );
        std::thread::sleep(POLL_INTERVAL);
    }
}

fn answer_message_box(
    app: &MirxApp,
    dialog: HWND,
    button: i32,
) -> Result<(), Box<dyn std::error::Error>> {
    assert_ne!(
        unsafe { PostMessageW(dialog, WM_COMMAND, button as WPARAM, 0) },
        0,
        "posting the message box answer must succeed"
    );
    let deadline = Instant::now() + Duration::from_secs(5);
    while unsafe { IsWindow(dialog) } != 0 {
        assert!(
            Instant::now() < deadline,
            "message box did not close within five seconds"
        );
        std::thread::sleep(POLL_INTERVAL);
    }
    app.wait_idle(Duration::from_secs(5))?;
    Ok(())
}

#[test]
fn closing_a_room_window_confirms_then_parts() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;

    let child = request_view_close(&app, &beta)?;
    let (dialog, text) = wait_for_message_box(&app);
    assert_eq!(text, "Leave Beta?\n\nYou may need a new invite to rejoin.");
    answer_message_box(&app, dialog, IDNO)?;
    assert_eq!(unsafe { IsWindow(child) }, 1);
    assert!(app.dump_model()?.submitted_membership_commands.is_empty());

    request_view_close(&app, &beta)?;
    let (dialog, _) = wait_for_message_box(&app);
    answer_message_box(&app, dialog, IDYES)?;
    let model = app.dump_model()?;
    assert_eq!(model.status, "part submitted: !beta:example");
    assert_eq!(
        model.submitted_membership_commands,
        vec![SubmittedMembershipCommand {
            action: MembershipCommandAction::Leave,
            target: "!beta:example".to_owned(),
        }]
    );
    // As in mIRC, the window stays until the part lands.
    assert_eq!(unsafe { IsWindow(child) }, 1);
    assert_eq!(app.dump_ui_state()?.mdi.active, beta);

    let mut rooms = close_lifecycle_rooms();
    rooms.retain(|room| room.room_id != "!beta:example");
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::SyncedRooms(rooms)])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(unsafe { IsWindow(child) }, 0);
    let ui_state = app.dump_ui_state()?;
    assert_ne!(ui_state.mdi.active, beta);
    assert!(ui_state.navigation.find_view(&beta).is_empty());
    assert_eq!(ui_state.switchbar.items.len(), ui_state.mdi.views.len());
    assert_compose_has_focus(&app);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Options > Chat's Join rooms when invited and Show in active:
/// Invites: an invite arriving in a room list prints in the window in
/// front and is accepted, and the window in front stays so.
#[test]
fn an_arriving_channel_invite_is_announced_and_auto_joined()
-> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    write_settings(&local_app_data, "[chat]\r\njoin_on_invite=on\r\n")?;
    let app = launch_automation_app(&mirx_ui_exe_path()?, &local_app_data)?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let alpha = room_identity("!alpha:example");
    app.select_view(alpha.clone())?;
    // The load's own list is the first: nothing is news.
    assert!(app.dump_model()?.submitted_membership_commands.is_empty());

    append_events(
        &app,
        vec![Event::SyncedRooms(vec![
            room_summary("!beta:example", "Beta", true),
            room_summary("!alpha:example", "Alpha", false),
            invited_room_summary("!invite:example", "Lobby", false),
        ])],
    )?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(
        view_lines_containing(find_view(&ui_state, &alpha), "invites you")
            .into_iter()
            .map(|line| line.split_once("] ").map_or(line, |(_, text)| text))
            .collect::<Vec<_>>(),
        ["* Bob (@bob:example) invites you to join Lobby"]
    );
    assert_eq!(
        app.dump_model()?.submitted_membership_commands,
        vec![SubmittedMembershipCommand {
            action: MembershipCommandAction::AcceptInvite,
            target: "!invite:example".to_owned(),
        }]
    );
    // The invite's window opened behind.
    assert_eq!(ui_state.mdi.active, alpha);
    find_view(&ui_state, &room_identity("!invite:example"));

    // The unauthenticated core refuses the accept, as a refused accept
    // prints (Status, for an invite's window has no lines of its own yet);
    // the window in front stays, and the invite stays an invite.
    app.wait_for_ui_state("the refused accept", Duration::from_secs(10), |ui_state| {
        ui_state.mdi.views.iter().any(|view| {
            view.identity == ViewIdentity::Status
                && view_contains(
                    view,
                    "accept room invitation requires an authenticated session",
                )
        })
    })?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, alpha);
    assert_eq!(
        find_ui_room(&ui_state, "!invite:example").membership,
        RoomMembership::Invite
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn closing_an_invite_window_confirms_then_rejects() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let invite = room_identity("!invite:example");
    app.select_view(invite.clone())?;

    let child = request_view_close(&app, &invite)?;
    let (dialog, text) = wait_for_message_box(&app);
    assert_eq!(text, "Reject the invite to Lobby?");
    answer_message_box(&app, dialog, IDYES)?;
    let model = app.dump_model()?;
    assert_eq!(model.status, "reject submitted: !invite:example");
    assert_eq!(
        model.submitted_membership_commands,
        vec![SubmittedMembershipCommand {
            action: MembershipCommandAction::RejectInvite,
            target: "!invite:example".to_owned(),
        }]
    );
    assert_eq!(unsafe { IsWindow(child) }, 1);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn closing_a_query_window_hides_it_until_its_next_message() -> Result<(), Box<dyn std::error::Error>>
{
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let alpha = room_identity("!alpha:example");
    app.select_view(alpha.clone())?;

    let child = close_view_without_prompt(&app, &alpha)?;
    assert_eq!(unsafe { IsWindow(child) }, 0);
    let ui_state = app.dump_ui_state()?;
    assert!(ui_state.mdi.views.iter().all(|view| view.identity != alpha));
    assert!(
        ui_state
            .switchbar
            .items
            .iter()
            .all(|item| item.identity != alpha)
    );
    assert_eq!(ui_state.navigation.find_view(&alpha).len(), 1);
    assert_compose_has_focus(&app);

    // A sync leaves it closed; the other side talking reopens it.
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::SyncedRooms(
        close_lifecycle_rooms(),
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert!(
        app.dump_ui_state()?
            .mdi
            .views
            .iter()
            .all(|view| view.identity != alpha)
    );
    app.append_synthetic_events(&serde_json::to_string(&vec![text_event(
        "!alpha:example",
        "@alice:example",
        1_700_000_120_000,
        "alpha second",
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert!(ui_state.mdi.views.iter().any(|view| view.identity == alpha));
    assert_ne!(ui_state.mdi.active, alpha);
    assert_switchbar_activity(&ui_state, &alpha, Some(ViewActivityLevel::Message));

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn automation_driver_irc_info_commands_echo_in_active_window()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    app.append_synthetic_events(&serde_json::to_string(&vec![
        room_members_event(
            "!beta:example",
            &[("@alice:example", "Alice"), ("@bob:example", "Bob")],
        ),
        room_members_event("!alpha:example", &[("@alice:example", "Alice")]),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    let alpha = room_identity("!alpha:example");
    app.select_view(beta.clone())?;

    for input in [
        "/names",
        "/whois alice",
        "/help names",
        "/msg alice hi there",
    ] {
        app.set_compose_text(input)?;
        app.send_compose_key(ComposeKey::Return)?;
        app.wait_idle(Duration::from_secs(5))?;
        assert_eq!(app.compose_text()?, "", "{input}");
    }
    // The server's answer to /whois.
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::UserProfile(
        UserProfile {
            user_id: "@alice:example".to_owned(),
            display_name: Some("Alice Liddell".to_owned()),
            presence: None,
        },
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, beta);
    let view = find_view(&ui_state, &beta);
    for line in [
        "] * Members of Beta: Alice Bob",
        "] * Alice is @alice:example (Alice Liddell)",
        "] * Alice shares rooms with you: Beta Alpha",
        "] * Alice's homeserver is example",
        "] * /names [#room] - list this room's members, or the named room's",
        "] -> *alice* hi there",
    ] {
        assert!(
            only_view_line_containing(view, line).ends_with(line),
            "{line:?} in {:?}",
            view.lines
        );
    }
    // /msg does not open or activate the query.
    assert!(!view_contains(find_view(&ui_state, &alpha), "hi there"));

    app.select_status_view()?;
    app.set_compose_text("/close")?;
    app.send_compose_key(ComposeKey::Return)?;
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, ViewIdentity::Status);
    assert!(view_contains(
        find_view(&ui_state, &ViewIdentity::Status),
        "* /close: the Status window cannot be closed"
    ));

    // /close closes the active window as its close button does: a query
    // window hides.
    app.select_view(alpha.clone())?;
    app.set_compose_text("/close")?;
    app.send_compose_key(ComposeKey::Return)?;
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert!(ui_state.mdi.views.iter().all(|view| view.identity != alpha));
    assert!(
        ui_state
            .switchbar
            .items
            .iter()
            .all(|item| item.identity != alpha)
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// The window menu's Font... id.
const SYSMENU_ID_FONT: WPARAM = 0x0110;

#[test]
fn default_text_font_is_fixedsys_in_every_window() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    for identity in [ViewIdentity::Status, room_identity("!beta:example")] {
        if identity == ViewIdentity::Status {
            app.select_status_view()?;
        } else {
            app.select_view(identity.clone())?;
        }
        let ui_state = app.dump_ui_state()?;
        assert_eq!(ui_state.mdi.active, identity);
        let font = &ui_state.text_font;
        assert_eq!(font.face, "Fixedsys", "{identity:?}");
        assert_eq!((font.points, font.bold), (9, false));
        assert!((12..=18).contains(&font.line_height), "{font:?}");
        assert!(font.edit_height < 28, "{font:?}");
        // The harness prefix has Wine's Tahoma and the installed Noto Emoji.
        assert_eq!(font.fallback_faces, ["Tahoma", "Noto Emoji"]);
        assert!(
            ui_state
                .active_system_menu_items
                .contains(&"&Font...".to_owned()),
            "{:?}",
            ui_state.active_system_menu_items
        );
    }
    assert_eq!(
        app.dump_ui_state()?.timestamp,
        UiTimestamp {
            show: true,
            format: "[HH:nn]".to_owned(),
        }
    );
    // Nothing changed, so nothing was written.
    assert!(!settings_file_path(&local_app_data).exists());
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn font_command_changes_and_persists_the_text_font() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let launch = || {
        launch_app_with_options(
            &exe_path,
            &[OsString::from("--automation")],
            launch_options(Some(local_app_data.clone())),
        )
    };

    let app = launch()?;
    let before = app.dump_ui_state()?.text_font;
    type_commands(&app, &["/font -b 12 Courier"])?;
    let ui_state = app.dump_ui_state()?;
    let font = &ui_state.text_font;
    assert_eq!(font.face, "Courier");
    assert_eq!((font.points, font.bold), (12, true));
    assert_ne!(font.line_height, before.line_height);
    // The fallback chain is rebuilt for the new font.
    assert_eq!(font.fallback_faces, before.fallback_faces);
    assert_eq!(ui_state.status_bar.text, "font: Courier 12 bold");
    assert!(
        fs::read_to_string(settings_file_path(&local_app_data))?
            .contains("\r\ntext=Courier,12,bold\r\n")
    );

    type_commands(&app, &["/font -i 12 Courier"])?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.status_bar.text, "* /font: unknown option -i");
    assert_eq!(ui_state.text_font.face, "Courier");
    drop(app);

    let app = launch()?;
    let font = app.dump_ui_state()?.text_font;
    assert_eq!(font.face, "Courier");
    assert_eq!((font.points, font.bold), (12, true));
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn nick_list_is_owner_drawn_in_the_text_font() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    app.select_view(room_identity("!beta:example"))?;
    let item_height = || unsafe {
        SendMessageW(active_room_member_list_hwnd(&app), LB_GETITEMHEIGHT, 0, 0) as i32
    };
    let members = unsafe { active_room_member_list_hwnd(&app) };
    assert_ne!(
        unsafe { window_style(members) } & LBS_OWNERDRAWFIXED as u32,
        0
    );
    // It takes several nicks, as mIRC's, and tells of double-clicks.
    let notifying = (LBS_EXTENDEDSEL | LBS_NOTIFY) as u32;
    assert_eq!(unsafe { window_style(members) } & notifying, notifying);
    // Items are a text font line tall, as the stock listbox makes them.
    assert_eq!(item_height(), app.dump_ui_state()?.text_font.line_height);

    type_commands(&app, &["/font 12 Courier"])?;
    let font = app.dump_ui_state()?.text_font;
    assert_eq!(font.face, "Courier");
    assert_eq!(item_height(), font.line_height);
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn font_dialog_from_the_window_menu_cancels_and_applies() -> Result<(), Box<dyn std::error::Error>>
{
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;
    let child = view_child_hwnd(&app, &beta)?;
    let open_dialog = || {
        // Posted: the dialog runs a modal loop inside the handler.
        assert_ne!(
            unsafe { PostMessageW(child, WM_SYSCOMMAND, SYSMENU_ID_FONT, 0) },
            0,
            "posting Font... must succeed"
        );
        wait_for_message_box(&app).0
    };

    let dialog = open_dialog();
    answer_message_box(&app, dialog, IDCANCEL)?;
    assert!(!settings_file_path(&local_app_data).exists());
    assert_eq!(app.dump_ui_state()?.text_font.face, "Fixedsys");

    // The dialog starts at the current font, so OK keeps it, and saves it.
    let dialog = open_dialog();
    answer_message_box(&app, dialog, IDOK)?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.status_bar.text, "font: Fixedsys 9");
    assert_eq!(ui_state.text_font.face, "Fixedsys");
    assert!(
        fs::read_to_string(settings_file_path(&local_app_data))?
            .contains("\r\ntext=Fixedsys,9\r\n")
    );
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn timestamp_command_toggles_formats_and_persists() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let launch = || -> Result<GuiTestApp, Box<dyn std::error::Error>> {
        let app = launch_app_with_options(
            &exe_path,
            &[OsString::from("--automation")],
            launch_options(Some(local_app_data.clone())),
        )?;
        app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
        let mut events = close_lifecycle_events();
        // A restore, so Status has lines (and counts the rooms).
        events.insert(1, Event::RestoredSession);
        // 2023-11-14 22:13:20 UTC; the harness runs in UTC.
        events.push(text_event(
            "!beta:example",
            "@bob:example",
            1_700_000_000_000,
            "timestamped hello",
        ));
        app.load_events(&serde_json::to_string(&events)?)?;
        app.wait_idle(Duration::from_secs(5))?;
        app.select_view(room_identity("!beta:example"))?;
        Ok(app)
    };
    let beta = room_identity("!beta:example");
    let hello_line = |app: &GuiTestApp| -> Result<String, Box<dyn std::error::Error>> {
        let ui_state = app.dump_ui_state()?;
        Ok(only_view_line_containing(find_view(&ui_state, &beta), "timestamped hello").to_owned())
    };

    let app = launch()?;
    assert!(hello_line(&app)?.starts_with("[22:13] <"));
    type_commands(&app, &["/timestamp off"])?;
    assert!(hello_line(&app)?.starts_with("<"), "{}", hello_line(&app)?);
    assert_eq!(app.dump_ui_state()?.status_bar.text, "timestamp: off");
    type_commands(&app, &["/timestamp -f [HH:nn:ss]", "/timestamp on"])?;
    assert!(hello_line(&app)?.starts_with("[22:13:20] <"));
    type_commands(&app, &["/timestamp"])?;
    let ui_state = app.dump_ui_state()?;
    assert!(
        only_view_line_containing(find_view(&ui_state, &beta), "* Timestamp is")
            .ends_with("] * Timestamp is on ([HH:nn:ss])")
    );
    // Timestamps change in every window, not just the active one.
    let status_lines = &find_view(&ui_state, &ViewIdentity::Status).lines;
    assert!(!status_lines.is_empty());
    assert!(
        status_lines
            .iter()
            .all(|line| line.starts_with('[') && line.as_bytes()[9] == b']'),
        "{status_lines:?}"
    );
    assert_eq!(
        fs::read_to_string(settings_file_path(&local_app_data))?,
        "[fonts]\r\ntext=Fixedsys,9\r\n\
         [timestamp]\r\nshow=on\r\nformat=[HH:nn:ss]\r\n\
         [connect]\r\nstartup=on\r\nreconnect=on\r\nretry=on\r\nretry_times=99\r\nretry_delay=10\r\n\
         [toolbar]\r\nshow=on\r\n\
         [switchbar]\r\nshow=on\r\nbuttons=120\r\n\
         event=5\r\nmessage=4\r\nhighlight=12\r\n\
         [treebar]\r\nshow=on\r\nwidth=240\r\n\
         [logging]\r\nrooms=off\r\ndirect=off\r\ntimestamp=on\r\n\
         [tray]\r\nalways=off\r\nstartup=off\r\nminimize=off\r\nsingle_click=off\r\n\
         [tips]\r\nhighlights=on\r\ndirect=on\r\nrooms=off\r\n\
         [marker]\r\nshow=on\r\ncolor=4\r\n\
         [typing]\r\nsend=on\r\n\
         [chat]\r\nrank_prefix=off\r\njoin_on_invite=off\r\n\
         active_away=on\r\nactive_invites=on\r\nactive_whois=on\r\n\
         [other]\r\nbuffer=5000\r\n\
         [colors]\r\nbackground=0\r\naction=6\r\nhighlight=5\r\ninfo=2\r\n\
         invite=3\r\njoin=3\r\nkick=3\r\nsettings=3\r\nnick=3\r\nnormal=1\r\n\
         notice=5\r\nnotify=7\r\nother=6\r\nown=1\r\npart=3\r\ntopic=3\r\neditbox=0\r\n\
         editbox_text=1\r\nlistbox=0\r\nlistbox_text=1\r\ngray=14\r\n\
         treebar=0\r\ntreebar_text=1\r\n[nickcolors]\r\nactive=on\r\n\
         [notify]\r\nactive=off\r\n\
         [perform]\r\nenabled=off\r\n"
    );
    drop(app);

    let app = launch()?;
    assert!(hello_line(&app)?.starts_with("[22:13:20] <"));
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// The window menu's Logging id.
const SYSMENU_ID_LOGGING: WPARAM = 0x0140;

fn log_file_path(local_app_data: &Path, stem: &str) -> PathBuf {
    local_app_data
        .join("mirx")
        .join("ui-shell")
        .join("logs")
        .join(format!("{stem}.log"))
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("the clock is past the epoch")
        .as_millis() as u64
}

/// `[HH:nn]` at `ms`, in UTC: the harness's time zone.
fn utc_hh_nn(ms: u64) -> String {
    let minutes = ms / 60_000 % (24 * 60);
    format!("[{:02}:{:02}]", minutes / 60, minutes % 60)
}

/// A log's lines, each session's start and close time checked to be
/// asctime's and replaced by `*`.
fn read_log(path: &Path) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let text = fs::read_to_string(path)?;
    let text = text
        .strip_suffix("\r\n")
        .ok_or_else(|| format!("{} must end with a line break: {text:?}", path.display()))?;
    Ok(text
        .split("\r\n")
        .map(|line| {
            for prefix in ["Session Start: ", "Session Close: "] {
                if let Some(time) = line.strip_prefix(prefix) {
                    // `Fri Nov 20 14:03:12 2026`
                    let fields = time.split(' ').collect::<Vec<_>>();
                    assert!(
                        fields.len() == 5
                            && fields[0].len() == 3
                            && fields[1].len() == 3
                            && fields[2].len() == 2
                            && fields[3].len() == 8
                            && fields[4].len() == 4,
                        "{line:?}"
                    );
                    return format!("{prefix}*");
                }
            }
            line.to_owned()
        })
        .collect())
}

/// A logged line without its `[HH:nn] ` timestamp, for lines whose time is
/// the clock's.
fn untimed(line: &str) -> &str {
    let bytes = line.as_bytes();
    assert!(
        bytes.len() > 8
            && bytes[0] == b'['
            && bytes[3] == b':'
            && bytes[6] == b']'
            && bytes[7] == b' ',
        "{line:?}"
    );
    &line[8..]
}

/// Writes `mirx.ini` with `ini`'s sections; the rest keep their defaults.
fn write_settings(local_app_data: &Path, ini: &str) -> Result<(), Box<dyn std::error::Error>> {
    let path = settings_file_path(local_app_data);
    fs::create_dir_all(path.parent().expect("mirx.ini is in the profile"))?;
    fs::write(path, ini)?;
    Ok(())
}

fn view_log(
    app: &MirxApp,
    identity: &ViewIdentity,
) -> Result<Option<String>, Box<dyn std::error::Error>> {
    Ok(find_view(&app.dump_ui_state()?, identity).log.clone())
}

#[test]
fn log_command_logs_a_windows_new_lines_until_turned_off() -> Result<(), Box<dyn std::error::Error>>
{
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;
    let last_line = |app: &MirxApp| -> Result<String, Box<dyn std::error::Error>> {
        let ui_state = app.dump_ui_state()?;
        Ok(untimed(find_view(&ui_state, &beta).lines.last().expect("a line")).to_owned())
    };

    type_commands(&app, &["/log"])?;
    assert_eq!(last_line(&app)?, "* Logging is off");
    assert_eq!(view_log(&app, &beta)?, None);

    type_commands(&app, &["/log on"])?;
    let path = view_log(&app, &beta)?.expect("Beta logs");
    assert!(path.ends_with(r"\logs\!beta.example.log"), "{path}");
    assert_eq!(last_line(&app)?, format!("* Logging on: {path}"));
    type_commands(&app, &["/log on"])?;
    assert_eq!(last_line(&app)?, format!("* Logging is already on: {path}"));

    let said_at = now_ms();
    app.append_synthetic_events(&serde_json::to_string(&vec![
        text_event("!beta:example", "@bob:example", said_at, "logged hello"),
        // Sent long ago, but it arrived while the log was on: a late event
        // is logged, with its server time.
        text_event(
            "!beta:example",
            "@bob:example",
            1_700_000_030_000,
            "older line",
        ),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    type_commands(&app, &["/log"])?;
    assert_eq!(last_line(&app)?, format!("* Logging is on: {path}"));
    type_commands(&app, &["/log off"])?;
    assert_eq!(last_line(&app)?, format!("* Logging off: {path}"));
    assert_eq!(view_log(&app, &beta)?, None);
    type_commands(&app, &["/log off"])?;
    assert_eq!(last_line(&app)?, "* Logging is already off");
    app.append_synthetic_events(&serde_json::to_string(&vec![text_event(
        "!beta:example",
        "@bob:example",
        now_ms(),
        "after the log",
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let log = read_log(&log_file_path(&local_app_data, "!beta.example"))?;
    assert_eq!(
        log[..2],
        [
            "Session Start: *".to_owned(),
            "Session Ident: Beta (!beta:example)".to_owned()
        ]
    );
    assert_eq!(log.last().map(String::as_str), Some("Session Close: *"));
    let lines = &log[2..log.len() - 1];
    assert_eq!(
        lines.iter().map(|line| untimed(line)).collect::<Vec<_>>(),
        [
            format!("* Logging on: {path}").as_str(),
            format!("* Logging is already on: {path}").as_str(),
            "<@bob:example> logged hello",
            "<@bob:example> older line",
            format!("* Logging is on: {path}").as_str(),
        ]
    );
    assert!(lines[2].starts_with(&utc_hh_nn(said_at)), "{lines:?}");
    assert!(lines[3].starts_with("[22:13] "), "{lines:?}");

    // Turned on again, the log goes on after a blank line.
    type_commands(&app, &["/log on"])?;
    let log = read_log(&log_file_path(&local_app_data, "!beta.example"))?;
    assert_eq!(
        log[log.len() - 4..log.len() - 1],
        [
            String::new(),
            "Session Start: *".to_owned(),
            "Session Ident: Beta (!beta:example)".to_owned()
        ]
    );
    assert_eq!(
        untimed(log.last().expect("a line")),
        format!("* Logging on: {path}")
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn log_command_errors_name_what_cannot_log() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    close_view_without_prompt(&app, &room_identity("!alpha:example"))?;
    app.select_view(room_identity("!beta:example"))?;
    for (input, error) in [
        (
            "/log on #nowhere:example",
            "* /log: unknown room: #nowhere:example",
        ),
        (
            "/log off !alpha:example",
            "* /log: !alpha:example has no open window",
        ),
        ("/log maybe", "* /log: usage: /log [on|off] [#room]"),
    ] {
        type_commands(&app, &[input])?;
        assert_eq!(app.dump_ui_state()?.status_bar.text, error, "{input}");
    }
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn log_command_turns_another_rooms_log_on_and_the_status_log()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let alpha = room_identity("!alpha:example");
    app.select_view(room_identity("!beta:example"))?;
    type_commands(&app, &["/log on !alpha:example"])?;
    let path = view_log(&app, &alpha)?.expect("Alpha logs");
    assert!(path.ends_with(r"\logs\@alice.example.log"), "{path}");
    assert_eq!(view_log(&app, &room_identity("!beta:example"))?, None);

    app.select_status_view()?;
    type_commands(&app, &["/log on", "/log"])?;
    let status_path = view_log(&app, &ViewIdentity::Status)?.expect("Status logs");
    assert!(status_path.ends_with(r"\logs\status.log"), "{status_path}");
    let log = read_log(&log_file_path(&local_app_data, "status"))?;
    assert_eq!(
        log.iter()
            .map(|line| untimed_or_session(line))
            .collect::<Vec<_>>(),
        [
            "Session Start: *",
            "Session Ident: Status",
            format!("* Logging on: {status_path}").as_str(),
            format!("* Logging is on: {status_path}").as_str(),
        ]
    );
    let log = read_log(&log_file_path(&local_app_data, "@alice.example"))?;
    assert_eq!(log[1], "Session Ident: Alpha (@alice:example)");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

fn untimed_or_session(line: &str) -> &str {
    if line.starts_with("Session ") {
        line
    } else {
        untimed(line)
    }
}

#[test]
fn rooms_log_automatically_as_the_options_say_and_exit_closes_the_logs()
-> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    write_settings(&local_app_data, "[logging]\r\nrooms=on\r\ndirect=off\r\n")?;
    let (app, local_app_data) = launch_close_lifecycle_app_in(local_app_data)?;
    let beta = room_identity("!beta:example");
    let alpha = room_identity("!alpha:example");
    let lobby = room_identity("!invite:example");
    let beta_path = view_log(&app, &beta)?.expect("a channel logs");
    assert!(
        beta_path.ends_with(r"\logs\!beta.example.log"),
        "{beta_path}"
    );
    assert_eq!(view_log(&app, &alpha)?, None, "a query does not");
    assert_eq!(view_log(&app, &lobby)?, None, "an invite does not, yet");
    app.select_view(beta.clone())?;
    assert_eq!(
        app.dump_ui_state()?.active_system_menu_checked,
        ["&Logging"]
    );
    app.select_view(alpha.clone())?;
    assert!(app.dump_ui_state()?.active_system_menu_checked.is_empty());

    // Joined, the invite is a channel, and logs.
    let mut rooms = close_lifecycle_rooms();
    rooms[2].membership = RoomMembership::Join;
    rooms[2].notification_mode = Some(RoomNotificationMode::AllMessages);
    rooms[2].invite = None;
    let said_at = now_ms();
    app.append_synthetic_events(&serde_json::to_string(&vec![
        Event::SyncedRooms(rooms),
        text_event("!beta:example", "@bob:example", said_at, "beta news"),
        text_event("!alpha:example", "@alice:example", said_at, "alpha news"),
        // In the batch that joined it, before its window decided.
        text_event("!invite:example", "@bob:example", said_at, "lobby hello"),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert!(
        view_log(&app, &lobby)?
            .expect("the joined room logs")
            .ends_with(r"\logs\!invite.example.log")
    );

    app.select_status_view()?;
    type_commands(&app, &["/log on"])?;

    let status = app.close(Duration::from_secs(30))?;
    assert!(status.success(), "mirx exited with {status}");
    assert_eq!(
        read_log(&log_file_path(&local_app_data, "status"))?.last(),
        Some(&"Session Close: *".to_owned())
    );
    assert_eq!(
        read_log(&log_file_path(&local_app_data, "!beta.example"))?,
        [
            "Session Start: *".to_owned(),
            "Session Ident: Beta (!beta:example)".to_owned(),
            // Loaded before Beta's window decided: it arrived all the same.
            "[22:13] <@bob:example> beta first".to_owned(),
            format!("{} <@bob:example> beta news", utc_hh_nn(said_at)),
            "Session Close: *".to_owned(),
        ]
    );
    assert_eq!(
        read_log(&log_file_path(&local_app_data, "!invite.example"))?,
        [
            "Session Start: *".to_owned(),
            "Session Ident: Lobby (!invite:example)".to_owned(),
            format!("{} <@bob:example> lobby hello", utc_hh_nn(said_at)),
            "Session Close: *".to_owned(),
        ]
    );
    assert!(!log_file_path(&local_app_data, "@alice.example").exists());

    // Queries only, the next time.
    write_settings(&local_app_data, "[logging]\r\nrooms=off\r\ndirect=on\r\n")?;
    let (app, local_app_data) = launch_close_lifecycle_app_in(local_app_data)?;
    assert_eq!(view_log(&app, &beta)?, None);
    assert!(view_log(&app, &alpha)?.is_some());
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn a_closed_query_reopened_by_a_message_logs_it() -> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    write_settings(&local_app_data, "[logging]\r\ndirect=on\r\n")?;
    let (app, local_app_data) = launch_close_lifecycle_app_in(local_app_data)?;
    let alpha = room_identity("!alpha:example");
    assert!(view_log(&app, &alpha)?.is_some());
    close_view_without_prompt(&app, &alpha)?;
    assert!(
        !app.dump_ui_state()?
            .mdi
            .views
            .iter()
            .any(|view| view.identity == alpha)
    );
    // Its server time is older than the window it opens: server time
    // does not decide.
    app.append_synthetic_events(&serde_json::to_string(&vec![text_event(
        "!alpha:example",
        "@alice:example",
        1_700_000_120_000,
        "back again",
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert!(view_log(&app, &alpha)?.is_some(), "the reopened query logs");
    let status = app.close(Duration::from_secs(30))?;
    assert!(status.success(), "mirx exited with {status}");

    let log = read_log(&log_file_path(&local_app_data, "@alice.example"))?;
    let session = [
        "Session Start: *".to_owned(),
        "Session Ident: Alpha (@alice:example)".to_owned(),
    ];
    assert_eq!(
        log,
        [
            session.as_slice(),
            &[
                "[22:14] <@alice:example> alpha first".to_owned(),
                "Session Close: *".to_owned(),
                String::new(),
            ],
            session.as_slice(),
            &[
                "[22:15] <@alice:example> back again".to_owned(),
                "Session Close: *".to_owned(),
            ],
        ]
        .concat()
    );
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn logs_are_plain_text_and_timestamps_can_go() -> Result<(), Box<dyn std::error::Error>> {
    let styled_event = || {
        let mut event = text_event("!beta:example", "@bob:example", now_ms(), "bold plain");
        let Event::RoomActivity(activity) = &mut event else {
            unreachable!()
        };
        let CoreRoomActivityKind::Message(message) = &mut activity.kind else {
            unreachable!()
        };
        message.styles = vec![mirx_core::TextStyleSpan {
            start: 0,
            end: 4,
            style: mirx_core::TextStyle {
                bold: true,
                ..mirx_core::TextStyle::default()
            },
        }];
        event
    };
    let mut logs = Vec::new();
    for logging in ["", "[logging]\r\ntimestamp=off\r\n"] {
        let local_app_data = unique_local_app_data_path();
        write_settings(&local_app_data, logging)?;
        let (app, local_app_data) = launch_close_lifecycle_app_in(local_app_data)?;
        app.select_view(room_identity("!beta:example"))?;
        type_commands(&app, &["/log on"])?;
        app.append_synthetic_events(&serde_json::to_string(&vec![styled_event()])?)?;
        app.wait_idle(Duration::from_secs(5))?;
        logs.push(read_log(&log_file_path(&local_app_data, "!beta.example"))?);
        drop(app);
        let _ = fs::remove_dir_all(&local_app_data);
    }
    // The bold is no text: a log never holds formatting.
    assert_ne!(logs[0][3], "<@bob:example> bold plain");
    assert_eq!(untimed(&logs[0][3]), "<@bob:example> bold plain");
    assert_eq!(logs[1][3], "<@bob:example> bold plain");
    Ok(())
}

#[test]
fn window_menu_logging_toggles_the_log_and_its_check() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;
    let child = view_child_hwnd(&app, &beta)?;
    let toggle = || -> Result<(), Box<dyn std::error::Error>> {
        // Sent, not posted: a posted command can come after the dump,
        // which the UI thread takes first as a sent message.
        unsafe { SendMessageW(child, WM_SYSCOMMAND, SYSMENU_ID_LOGGING, 0) };
        app.wait_idle(Duration::from_secs(5))?;
        Ok(())
    };
    toggle()?;
    let ui_state = app.dump_ui_state()?;
    let path = find_view(&ui_state, &beta).log.clone().expect("Beta logs");
    assert_eq!(ui_state.active_system_menu_checked, ["&Logging"]);
    assert_eq!(
        untimed(find_view(&ui_state, &beta).lines.last().expect("a line")),
        format!("* Logging on: {path}")
    );
    toggle()?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(find_view(&ui_state, &beta).log, None);
    assert!(ui_state.active_system_menu_checked.is_empty());
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn a_thread_windows_logging_is_its_rooms() -> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    let app = launch_automation_app(&mirx_ui_exe_path()?, &local_app_data)?;
    app.load_events(&fs::read_to_string(fixture_state_path(
        "message-edits.json",
    ))?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let ops = room_identity("!ops:example");
    let thread = thread_identity("!ops:example", "$thread-root");
    app.select_view(thread.clone())?;
    let child = view_child_hwnd(&app, &thread)?;
    // Sent, not posted: a posted command can come after the dump.
    unsafe { SendMessageW(child, WM_SYSCOMMAND, SYSMENU_ID_LOGGING, 0) };
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    let path = find_view(&ui_state, &ops)
        .log
        .clone()
        .expect("the room logs");
    assert_eq!(find_view(&ui_state, &thread).log.as_ref(), Some(&path));
    assert_eq!(ui_state.active_system_menu_checked, ["&Logging"]);
    app.select_view(ops.clone())?;
    assert_eq!(
        app.dump_ui_state()?.active_system_menu_checked,
        ["&Logging"]
    );
    // The room's `/log off` clears the thread window's check too.
    type_commands(&app, &["/log off"])?;
    app.select_view(thread.clone())?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(find_view(&ui_state, &thread).log, None);
    assert!(ui_state.active_system_menu_checked.is_empty());
    // A new thread window of a logging room starts checked.
    type_commands(&app, &["/log on"])?;
    let child = close_view_without_prompt(&app, &thread)?;
    assert_eq!(unsafe { IsWindow(child) }, 0);
    app.select_view(thread.clone())?;
    assert_eq!(
        app.dump_ui_state()?.active_system_menu_checked,
        ["&Logging"]
    );
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

