#[test]
fn clicking_a_tip_opens_its_window() -> Result<(), Box<dyn std::error::Error>> {
    let alpha = room_identity("!alpha:example");
    let (app, local_app_data) = launch_hidden_in_tray("")?;
    assert_ne!(app.dump_ui_state()?.mdi.active, alpha);
    append_events(
        &app,
        vec![text_event(
            "!alpha:example",
            "@alice:example",
            now_ms(),
            "hi",
        )],
    )?;
    assert_eq!(shown_tips(&app)?.len(), 1);
    tray_icon_event(&app, NIN_BALLOONUSERCLICK)?;
    assert_eq!(frame_shown(&app), (true, false));
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, alpha);
    assert_eq!((ui_state.tray.icon, ui_state.tray.hidden), (false, false));
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);

    // A tip that times out leaves mirx where it was, its icon kept.
    let (app, local_app_data) = launch_hidden_in_tray("")?;
    append_events(
        &app,
        vec![text_event(
            "!alpha:example",
            "@alice:example",
            now_ms(),
            "hi",
        )],
    )?;
    tray_icon_event(&app, NIN_BALLOONTIMEOUT)?;
    assert_eq!(tray_icon_and_hidden(&app)?, (true, true));
    assert!(!frame_shown(&app).0);
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn taskbar_created_adds_the_icon_again() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_with_tray("always=on\r\n")?;
    assert_eq!(tray_icon_and_hidden(&app)?, (true, false));
    let name = wide_null("TaskbarCreated");
    let taskbar_created = unsafe { RegisterWindowMessageW(name.as_ptr()) };
    assert_ne!(taskbar_created, 0);
    let frame = app.automation_frame_hwnd() as HWND;
    let mut result = 0;
    assert_ne!(
        unsafe {
            SendMessageTimeoutW(
                frame,
                taskbar_created,
                0,
                0,
                SMTO_NORMAL,
                5_000,
                &mut result,
            )
        },
        0
    );
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(tray_icon_and_hidden(&app)?, (true, false));
    assert!(!status_view_contains(&app, "Tray icon unavailable")?);
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

fn ranked_member(
    user_id: &str,
    display_name: &str,
    rank: RoomMemberRank,
    moderatable: bool,
) -> RoomMemberSummary {
    RoomMemberSummary {
        user_id: user_id.to_owned(),
        nick: display_name.to_owned(),
        nick_ambiguous: false,
        is_own_user: false,
        rank,
        can_kick: moderatable,
        can_ban: moderatable,
    }
}

/// The `UpdateRoomSettings` of `/op` and the nick list's Control items:
/// only member roles.
fn member_roles_update(
    room_id: &str,
    roles: &[(&str, MemberPowerRole)],
) -> SubmittedRoomSettingsCommand {
    SubmittedRoomSettingsCommand::Update {
        room_id: room_id.to_owned(),
        topic_by_operators: None,
        moderated: None,
        member_roles: roles
            .iter()
            .map(|(user_id, role)| SubmittedPowerLevelChange {
                user_id: (*user_id).to_owned(),
                role: *role,
            })
            .collect(),
        invite_only: None,
        name: None,
        topic: None,
        listed_in_directory: None,
        unban: Vec::new(),
    }
}

#[test]
fn automation_driver_irc_moderation_commands_submit_core_commands()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::RoomMembers(
        RoomMembers {
            room_id: "!beta:example".to_owned(),
            members: vec![
                ranked_member("@alice:example", "Alice", RoomMemberRank::Member, true),
                ranked_member("@bob:example", "Bob", RoomMemberRank::Moderator, false),
                ranked_member("@vic:example", "Vic", RoomMemberRank::Voiced, false),
            ],
        },
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    app.select_view(room_identity("!beta:example"))?;

    for input in [
        "/kick alice spamming links",
        "/ban Alice",
        "/unban @gone:example",
        "/invite @carol:example",
        "/op alice",
        "/voice alice",
        "/deop Bob",
        "/devoice Vic",
        "/op alice Vic",
        // Bob already has moderator power: nothing is sent for Alice either.
        "/op alice Bob",
        "/nick New Name",
    ] {
        app.set_compose_text(input)?;
        app.send_compose_key(ComposeKey::Return)?;
        app.wait_idle(Duration::from_secs(5))?;
        assert_eq!(app.compose_text()?, "", "{input}");
    }

    let model = app.dump_model()?;
    let moderation =
        |action, user_id: &str, reason: Option<&str>| SubmittedMemberModerationCommand {
            action,
            room_id: "!beta:example".to_owned(),
            user_id: user_id.to_owned(),
            reason: reason.map(str::to_owned),
        };
    assert_eq!(
        model.submitted_member_moderation_commands,
        vec![
            moderation(
                MemberModerationAction::Kick,
                "@alice:example",
                Some("spamming links")
            ),
            moderation(MemberModerationAction::Ban, "@alice:example", None),
            moderation(MemberModerationAction::Unban, "@gone:example", None),
            moderation(MemberModerationAction::Invite, "@carol:example", None),
        ]
    );
    let power = |roles: &[(&str, MemberPowerRole)]| member_roles_update("!beta:example", roles);
    assert_eq!(
        model.submitted_room_settings_commands,
        vec![
            power(&[("@alice:example", MemberPowerRole::Moderator)]),
            power(&[("@alice:example", MemberPowerRole::Voiced)]),
            power(&[("@bob:example", MemberPowerRole::Default)]),
            power(&[("@vic:example", MemberPowerRole::Default)]),
            // One command, one write, for both.
            power(&[
                ("@alice:example", MemberPowerRole::Moderator),
                ("@vic:example", MemberPowerRole::Moderator),
            ]),
        ]
    );
    assert_eq!(
        model.submitted_profile_commands,
        vec![SubmittedProfileCommand {
            display_name: "New Name".to_owned(),
        }]
    );

    // The unauthenticated core answers each one, which proves they reached
    // it: the room's errors in its window, the account's in Status.
    let ui_state = app.dump_ui_state()?;
    let beta = find_view(&ui_state, &room_identity("!beta:example"));
    let status = find_view(&ui_state, &ViewIdentity::Status);
    for (view, operation) in [
        (beta, "kick room member"),
        (beta, "ban room member"),
        (beta, "unban room member"),
        (beta, "invite room member"),
        (beta, "update room settings"),
        (status, "set display name"),
    ] {
        assert!(
            view_contains(
                view,
                &format!("{operation} requires an authenticated session")
            ),
            "{operation}: {:?}",
            view.lines
        );
    }
    assert!(!view_contains(status, "room member"), "{:?}", status.lines);
    assert!(
        view_contains(beta, "* /op: Bob already has moderator power"),
        "{:?}",
        beta.lines
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

