#[test]
fn automation_driver_inactive_thread_activity_marks_only_thread_until_reactivated()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let fixture_path = fixture_state_path("thread-hierarchy.json");
    let args = [OsString::from("--automation")];
    let app = launch_app(&exe_path, &args)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&fs::read_to_string(&fixture_path)?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let room_view_identity = room_identity("!ops:example");
    let thread_view_identity = thread_identity("!ops:example", "$thread-root");

    app.select_view(thread_view_identity.clone())?;
    app.select_room("!ops:example")?;

    app.append_synthetic_events(&serde_json::to_string(&vec![
        message_event_with_event_id_and_relation(
            "!ops:example",
            "$thread-activity-2",
            "@erin:example",
            1_700_000_300_000,
            Some(CoreRoomActivityRelation::Thread {
                thread_root_event_id: "$thread-root".to_owned(),
                in_reply_to_event_id: Some("$thread-1".to_owned()),
                is_falling_back: false,
            }),
            CoreRoomMessagePresentationKind::Text,
            "thread follow-up",
        ),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let inactive_thread_state = app.dump_ui_state()?;
    assert_eq!(inactive_thread_state.mdi.active, room_view_identity);
    assert_eq!(
        inactive_thread_state
            .switchbar
            .items
            .iter()
            .map(|item| item.identity.clone())
            .collect::<Vec<_>>(),
        vec![
            ViewIdentity::Status,
            room_view_identity.clone(),
            thread_view_identity.clone(),
        ]
    );
    assert_active_switchbar_item(&inactive_thread_state, &room_view_identity);
    assert_switchbar_activity(&inactive_thread_state, &room_view_identity, None);
    assert_switchbar_activity(
        &inactive_thread_state,
        &thread_view_identity,
        Some(ViewActivityLevel::Message),
    );
    assert_eq!(
        find_switchbar_item(&inactive_thread_state, &thread_view_identity).title,
        "Thread: root msg"
    );

    app.select_view(thread_view_identity.clone())?;
    let reactivated_thread_state = app.dump_ui_state()?;
    assert_eq!(reactivated_thread_state.mdi.active, thread_view_identity);
    assert_active_switchbar_item(&reactivated_thread_state, &thread_view_identity);
    assert_switchbar_activity(&reactivated_thread_state, &room_view_identity, None);
    assert_switchbar_activity(&reactivated_thread_state, &thread_view_identity, None);

    Ok(())
}

#[test]
fn automation_driver_applies_receive_side_message_edits_in_place()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let fixture_path = fixture_state_path("message-edits.json");
    let update_path = fixture_update_path("message-edits.json");
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let args = [OsString::from("--automation")];
    let app = launch_app_with_options(&exe_path, &args, options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&fs::read_to_string(&fixture_path)?)?;
    app.wait_idle(Duration::from_secs(5))?;

    assert_eq!(
        app.room_activity(Some("!ops:example"))?,
        vec![
            text_entry_with_event_id(
                "!ops:example",
                "$ops-room-1",
                "@alice:example",
                1_700_000_000_000,
                "lobby draft",
            ),
            text_entry_with_event_id(
                "!ops:example",
                "$thread-root",
                "@bob:example",
                1_700_000_060_000,
                "root msg draft",
            ),
            text_entry_with_event_id_and_relation(
                "!ops:example",
                "$thread-1",
                "@carol:example",
                1_700_000_120_000,
                Some(RoomActivityRelation::Thread {
                    thread_root_event_id: "$thread-root".to_owned(),
                    in_reply_to_event_id: Some("$thread-root".to_owned()),
                    is_falling_back: false,
                }),
                "thread reply",
            ),
        ]
    );

    app.append_synthetic_events(&fs::read_to_string(&update_path)?)?;
    app.wait_idle(Duration::from_secs(5))?;

    assert_eq!(
        app.room_activity(Some("!ops:example"))?,
        vec![
            text_entry_with_event_id(
                "!ops:example",
                "$ops-room-1",
                "@alice:example",
                1_700_000_000_000,
                "lobby edited",
            ),
            text_entry_with_event_id(
                "!ops:example",
                "$thread-root",
                "@bob:example",
                1_700_000_060_000,
                "root msg edited",
            ),
            text_entry_with_event_id_and_relation(
                "!ops:example",
                "$thread-1",
                "@carol:example",
                1_700_000_120_000,
                Some(RoomActivityRelation::Thread {
                    thread_root_event_id: "$thread-root".to_owned(),
                    in_reply_to_event_id: Some("$thread-root".to_owned()),
                    is_falling_back: false,
                }),
                "thread reply",
            ),
        ]
    );

    let ui_state = app.dump_ui_state()?;
    let room_view = find_view(&ui_state, &room_identity("!ops:example"));
    assert!(view_contains(room_view, "lobby edited"));
    assert!(view_contains(room_view, "root msg edited"));
    assert!(!view_contains(room_view, "lobby draft"));
    assert!(!view_contains(room_view, "root msg draft"));

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Each line that could not be decrypted says why. Read again, a line still
/// undecryptable takes its current cause in place; one whose key came
/// becomes its message in place.
#[test]
fn automation_driver_undecryptable_lines_say_why_and_take_a_new_cause_in_place()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let args = [OsString::from("--automation")];
    let app = launch_app_with_options(&exe_path, &args, options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&fs::read_to_string(fixture_state_path(
        "undecryptable-causes.json",
    ))?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let room = room_identity("!encrypted:example.org");
    let undecrypted = "sent an encrypted message that could not be decrypted";
    let lines = |app: &MirxApp| -> Result<Vec<String>, Box<dyn std::error::Error>> {
        let state = app.dump_ui_state()?;
        Ok(find_view(&state, &room).lines.clone())
    };
    let before = lines(&app)?;
    let shown = before
        .iter()
        .filter(|line| line.contains(undecrypted))
        .map(|line| line.split_once(undecrypted).expect("filtered").1)
        .collect::<Vec<_>>();
    assert_eq!(
        shown,
        [
            "",
            " (sent before you joined)",
            " (sent before this session existed, and you have no key backup)",
            " (sent before this session existed: /verify this session or /e2ee recover to read it)",
            " (the sender shares keys only with verified sessions: /verify this session)",
            " (the sender withheld its key)",
        ],
        "{before:#?}"
    );
    let historical = before
        .iter()
        .position(|line| line.contains("/e2ee recover"))
        .expect("the historical line");
    let read_again = |kind: serde_json::Value| {
        serde_json::json!([{ "RoomEventsDecrypted": {
            "room_id": "!encrypted:example.org",
            "events": [{
                "type": "activity",
                "room_id": "!encrypted:example.org",
                "activity_id": "event:$utd-historical-unverified:example.org",
                "timestamp_ms": 1_710_000_180_000u64,
                "highlight": false,
                "relation": null,
                "kind": kind,
            }],
        }}])
        .to_string()
    };
    let bob = serde_json::json!({
        "user_id": "@bob:example.org",
        "nick": "Bob",
        "nick_ambiguous": false,
    });

    // Verified, without the key in the backup: nothing more to say.
    app.append_synthetic_events(&read_again(serde_json::json!({
        "type": "unable_to_decrypt",
        "event_id": "$utd-historical-unverified:example.org",
        "sender": bob,
        "session_id": "SESSION3",
        "cause": "unknown",
    })))?;
    app.wait_idle(Duration::from_secs(5))?;
    let after = lines(&app)?;
    assert_eq!(after.len(), before.len(), "{after:#?}");
    assert!(
        after[historical].ends_with(&format!("* Bob {undecrypted}")),
        "{after:#?}"
    );
    assert!(!after.iter().any(|line| line.contains("/e2ee recover")));

    app.append_synthetic_events(&read_again(serde_json::json!({
        "type": "message",
        "event_id": "$utd-historical-unverified:example.org",
        "transaction_id": null,
        "sender": bob,
        "presentation": "text",
        "body": "from before you were here",
        "styles": [],
        "user_links": [],
        "send_state": { "state": "sent" },
    })))?;
    app.wait_idle(Duration::from_secs(5))?;
    let decrypted = lines(&app)?;
    assert!(
        decrypted[historical].ends_with("<Bob> from before you were here"),
        "{decrypted:#?}"
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Deleting an edit shows what it replaced: the latest edit left, then the
/// message's own text, no longer `(edited)`.
#[test]
fn automation_driver_a_redacted_edit_restores_the_previous_text()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let args = [OsString::from("--automation")];
    let app = launch_app_with_options(&exe_path, &args, options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&fs::read_to_string(fixture_state_path(
        "message-edits.json",
    ))?)?;
    app.wait_idle(Duration::from_secs(5))?;
    // `lobby edited` at 180000.
    app.append_synthetic_events(&fs::read_to_string(fixture_update_path(
        "message-edits.json",
    ))?)?;
    let later_edit = serde_json::json!([{ "RoomActivityUpdate": {
        "room_id": "!ops:example",
        "target": { "type": "event", "event_id": "$ops-room-1" },
        "kind": {
            "type": "message_replaced",
            "replacement_event_id": "$edit-room-2",
            "sender": "@alice:example",
            "timestamp_ms": 1_700_000_300_000u64,
            "presentation": "text",
            "body": "lobby final",
            "styles": [],
            "user_links": [],
        },
    }}]);
    app.append_synthetic_events(&later_edit.to_string())?;
    app.wait_idle(Duration::from_secs(5))?;
    let redact = |edit: &str| {
        serde_json::json!([{ "RoomActivityUpdate": {
            "room_id": "!ops:example",
            "target": { "type": "event", "event_id": edit },
            "kind": {
                "type": "activity_redacted",
                "redaction_event_id": format!("$redact{edit}"),
            },
        }}])
        .to_string()
    };
    let lobby_line = |app: &MirxApp| -> Result<String, Box<dyn std::error::Error>> {
        let state = app.dump_ui_state()?;
        let view = find_view(&state, &room_identity("!ops:example"));
        Ok(only_view_line_containing(view, "lobby").to_owned())
    };
    assert!(
        lobby_line(&app)?.ends_with("lobby final (edited)"),
        "{}",
        lobby_line(&app)?
    );

    app.append_synthetic_events(&redact("$edit-room-2"))?;
    app.wait_idle(Duration::from_secs(5))?;
    let line = lobby_line(&app)?;
    assert!(line.ends_with("lobby edited (edited)"), "{line}");

    app.append_synthetic_events(&redact("$edit-room-1"))?;
    app.wait_idle(Duration::from_secs(5))?;
    let line = lobby_line(&app)?;
    assert!(line.ends_with("lobby draft"), "{line}");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

