/// Perform on connect runs its lines as typed in Status on each connect
/// (an appended `SyncConnected`), never for a replayed load, and not at
/// all when it is off.
#[test]
fn perform_runs_in_status_on_each_connect() -> Result<(), Box<dyn std::error::Error>> {
    let performed = |app: &GuiTestApp| -> Result<Vec<String>, Box<dyn std::error::Error>> {
        Ok(status_view_lines(app)?
            .into_iter()
            .filter(|line| line.ends_with("performed") || line.contains("(in perform)"))
            .collect())
    };
    let launch = |enabled: &str| -> Result<(GuiTestApp, PathBuf), Box<dyn std::error::Error>> {
        let local_app_data = unique_local_app_data_path();
        write_settings(
            &local_app_data,
            &format!(
                "[perform]\r\nenabled={enabled}\r\nn0=join #perform:example\r\n\
                 n1=say hi\r\nn2=echo -s performed\r\n"
            ),
        )?;
        let app = launch_automation_app(&mirx_ui_exe_path()?, &local_app_data)?;
        let mut events = base_events();
        events.insert(
            1,
            Event::LoggedIn {
                session: core_stored_session(),
                homeserver_url: "https://matrix.example/".to_owned(),
            },
        );
        events.push(Event::SyncConnected);
        app.load_events(&serde_json::to_string(&events)?)?;
        app.wait_idle(Duration::from_secs(5))?;
        Ok((app, local_app_data))
    };
    let (app, local_app_data) = launch("on")?;
    let alpha = room_identity("!alpha:example");
    app.select_view(alpha.clone())?;
    // The load replays a connect: nothing runs.
    assert!(performed(&app)?.is_empty());
    let alpha_lines = find_view(&app.dump_ui_state()?, &alpha).lines.clone();

    append_events(&app, vec![Event::SyncConnected])?;
    let lines = performed(&app)?;
    assert_eq!(lines.len(), 2, "{lines:?}");
    assert!(lines[0].ends_with("* /say: no room selected (in perform)"));
    assert_eq!(lines[1], "performed");
    let model = app.dump_model()?;
    assert_eq!(
        model.submitted_membership_commands,
        vec![SubmittedMembershipCommand {
            action: MembershipCommandAction::Join,
            target: "#perform:example".to_owned(),
        }]
    );
    assert!(model.submitted_message_commands.is_empty());
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, alpha);
    assert_eq!(find_view(&ui_state, &alpha).lines, alpha_lines);

    // A reconnect performs again.
    append_events(&app, vec![Event::SyncStarted, Event::SyncConnected])?;
    let lines = performed(&app)?;
    assert_eq!(lines.len(), 4, "{lines:?}");
    assert_eq!(lines[3], "performed");
    assert_eq!(app.dump_model()?.submitted_membership_commands.len(), 2);
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);

    let (app, local_app_data) = launch("off")?;
    append_events(&app, vec![Event::SyncConnected])?;
    assert!(performed(&app)?.is_empty());
    assert!(app.dump_model()?.submitted_membership_commands.is_empty());
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Perform's commands run in order, each once the core answered what the
/// one before sent: the join's refusal (the automation's core is not
/// signed in) prints before the echo after it, and the next line after
/// both. `wait_idle` covers the whole run: an ack, the posted resume, the
/// next command.
#[test]
fn perform_runs_each_command_after_the_core_answers_the_one_before()
-> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    write_settings(
        &local_app_data,
        "[perform]\r\nenabled=on\r\nn0=join #perform:example | echo -s after join\r\n\
         n1=echo -s line two\r\n",
    )?;
    let app = launch_automation_app(&mirx_ui_exe_path()?, &local_app_data)?;
    let mut events = base_events();
    events.insert(
        1,
        Event::LoggedIn {
            session: core_stored_session(),
            homeserver_url: "https://matrix.example/".to_owned(),
        },
    );
    app.load_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let before = status_view_lines(&app)?.len();

    append_events(&app, vec![Event::SyncConnected])?;
    let lines = status_view_lines(&app)?[before..].to_vec();
    let position = |wanted: &dyn Fn(&str) -> bool| {
        lines
            .iter()
            .position(|line| wanted(line))
            .unwrap_or_else(|| panic!("not in Status: {lines:?}"))
    };
    let refusal = position(&|line| line.contains("join room requires an authenticated session"));
    let after_join = position(&|line| line == "after join");
    let line_two = position(&|line| line == "line two");
    assert!(refusal < after_join && after_join < line_two, "{lines:?}");
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// A Commands prompt runs its command in the window it was opened from,
/// even when a join completing meanwhile activated another one.
#[test]
fn a_commands_menu_prompt_acts_in_the_window_it_was_opened_from()
-> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    let app = launch_automation_app(&mirx_ui_exe_path()?, &local_app_data)?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let alpha = room_identity("!alpha:example");
    let beta = room_identity("!beta:example");
    app.select_view(alpha.clone())?;

    let frame_value = app.automation_frame_hwnd();
    let menu_thread = std::thread::spawn(move || unsafe {
        SendMessageW(
            frame_value as HWND,
            WM_COMMAND,
            (MENU_ID_COMMANDS_FIRST + COMMANDS_MENU_INVITE) as WPARAM,
            0,
        );
    });
    let class_name = wide_null("mirxWin32SingleFieldDialog");
    wait_for_window(&class_name, "Commands prompt")?;
    // The prompt's modal loop handles the core's answer to an earlier join.
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::RoomJoined(
        RoomJoined {
            room_id: "!beta:example".to_owned(),
            alias: None,
        },
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(app.dump_ui_state()?.mdi.active, beta);

    answer_commands_prompt("@carol:example")?;
    menu_thread
        .join()
        .expect("Commands menu thread must not panic");
    app.wait_idle(Duration::from_secs(5))?;

    let model = app.dump_model()?;
    assert_eq!(
        model.submitted_member_moderation_commands,
        vec![SubmittedMemberModerationCommand {
            action: MemberModerationAction::Invite,
            room_id: "!alpha:example".to_owned(),
            user_id: "@carol:example".to_owned(),
            reason: None,
        }]
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

fn menu(label: &str, items: &[(&str, bool)]) -> UiMenu {
    UiMenu {
        label: label.to_owned(),
        items: items
            .iter()
            .map(|(label, enabled)| UiMenuItem {
                label: (*label).to_owned(),
                enabled: *enabled,
                checked: false,
            })
            .collect(),
    }
}

/// View, with each bar's item checked while the bar is shown.
fn view_menu(switchbar: bool, treebar: bool) -> UiMenu {
    view_menu_with_toolbar(true, switchbar, treebar)
}

fn view_menu_with_toolbar(toolbar: bool, switchbar: bool, treebar: bool) -> UiMenu {
    UiMenu {
        label: "&View".to_owned(),
        items: [
            ("T&oolbar", toolbar),
            ("&Switchbar", switchbar),
            ("&Treebar", treebar),
        ]
        .into_iter()
        .map(|(label, checked)| UiMenuItem {
            label: label.to_owned(),
            enabled: true,
            checked,
        })
        .collect(),
    }
}

