/// Waits for the Options dialog to be open and shown, and returns it.
fn wait_for_options_dialog(app: &MirxApp) -> Result<HWND, Box<dyn std::error::Error>> {
    let dialog = wait_for_window(&wide_null("mirxWin32OptionsDialog"), "Options dialog")?;
    app.wait_for_ui_state("the Options dialog", Duration::from_secs(5), |ui_state| {
        ui_state.options_dialog.is_some()
    })?;
    assert_eq!(unsafe { read_window_text(dialog) }, "mirx Options");
    Ok(dialog)
}

/// Opens Tools > Options... from another thread, which the menu command
/// blocks until the dialog closes.
fn open_options_from_menu(app: &MirxApp) -> std::thread::JoinHandle<()> {
    let frame_value = app.automation_frame_hwnd();
    std::thread::spawn(move || unsafe {
        SendMessageW(
            frame_value as HWND,
            WM_COMMAND,
            MENU_ID_TOOLS_OPTIONS as WPARAM,
            0,
        );
    })
}

unsafe fn set_options_check(dialog: HWND, id: i32, checked: bool) {
    unsafe { SendMessageW(GetDlgItem(dialog, id), BM_SETCHECK, checked as WPARAM, 0) };
}

unsafe fn set_options_text(dialog: HWND, id: i32, text: &str) {
    let text = wide_null(text);
    unsafe { SetWindowTextW(GetDlgItem(dialog, id), text.as_ptr()) };
}

fn post_options_command(dialog: HWND, id: i32) -> Result<(), Box<dyn std::error::Error>> {
    assert_ne!(
        unsafe { PostMessageW(dialog, WM_COMMAND, id as WPARAM, 0) },
        0
    );
    Ok(())
}

#[test]
fn options_dialog_saves_connect_timestamp_and_buttons() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let frame = app.automation_frame_hwnd() as HWND;
    unsafe { SetForegroundWindow(frame) };
    press_keys(&[VK_MENU, u16::from(b'O')]);
    let dialog = wait_for_options_dialog(&app)?;
    let options = app
        .dump_ui_state()?
        .options_dialog
        .expect("the dialog is open");
    assert_eq!(
        options.tree,
        [
            "Connect",
            "Connect/Options",
            "Chat",
            "Chat/Messages",
            "Chat/Highlight",
            "Chat/Logging",
            "Display",
            "Display/Tray",
            "Display/Tips",
            "Other"
        ]
    );
    assert_eq!(options.selected, "Connect/Options");
    assert_eq!(
        options.visible_controls,
        [
            OPTIONS_CONNECT_ON_STARTUP_ID as u16,
            OPTIONS_RECONNECT_ID as u16,
            OPTIONS_RETRY_ID as u16,
            OPTIONS_RETRY_TIMES_ID as u16,
            OPTIONS_RETRY_DELAY_ID as u16,
            OPTIONS_PERFORM_ID as u16,
        ]
    );

    // Down from Connect/Options is the Chat category, which has a page of
    // its own; Down again is Chat > Messages.
    let tree = unsafe { GetDlgItem(dialog, 6001) };
    let mut ui_state = None;
    for page in ["Chat", "Chat/Messages"] {
        assert_ne!(
            unsafe { PostMessageW(tree, WM_KEYDOWN, VK_DOWN as WPARAM, 0) },
            0
        );
        ui_state = Some(
            app.wait_for_ui_state(page, Duration::from_secs(5), |ui_state| {
                ui_state
                    .options_dialog
                    .as_ref()
                    .is_some_and(|options| options.selected == page)
            })?,
        );
    }
    let ui_state = ui_state.expect("two pages were shown");
    let options = ui_state.options_dialog.expect("the dialog is open");
    assert_eq!(
        options.visible_controls,
        [
            OPTIONS_TIMESTAMP_SHOW_ID as u16,
            OPTIONS_TIMESTAMP_FORMAT_ID as u16,
            OPTIONS_TIMESTAMP_TOKENS_ID,
            OPTIONS_SEND_TYPING_ID as u16,
        ]
    );
    assert_eq!(
        unsafe { read_window_text(GetDlgItem(dialog, OPTIONS_TIMESTAMP_FORMAT_ID)) },
        "[HH:nn]"
    );

    app.select_options_page("Other")?;
    let options = app
        .dump_ui_state()?
        .options_dialog
        .expect("the dialog is open");
    assert_eq!(options.selected, "Other");
    assert_eq!(options.visible_controls, [OPTIONS_WINDOW_BUFFER_ID as u16]);
    assert_eq!(
        unsafe { read_window_text(GetDlgItem(dialog, OPTIONS_WINDOW_BUFFER_ID)) },
        "5000"
    );

    // Controls on hidden pages take their values too.
    unsafe {
        set_options_check(dialog, OPTIONS_CONNECT_ON_STARTUP_ID, false);
        set_options_check(dialog, OPTIONS_TIMESTAMP_SHOW_ID, false);
        set_options_text(dialog, OPTIONS_TIMESTAMP_FORMAT_ID, "[HH:nn:ss]");
        set_options_text(dialog, OPTIONS_SWITCHBAR_BUTTONS_ID, "90");
        set_options_text(dialog, OPTIONS_WINDOW_BUFFER_ID, "20000");
    }
    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    app.wait_idle(Duration::from_secs(5))?;

    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.options_dialog, None);
    assert_eq!(
        ui_state.timestamp,
        UiTimestamp {
            show: false,
            format: "[HH:nn:ss]".to_owned(),
        }
    );
    assert!(!ui_state.switchbar.items.is_empty());
    assert!(
        ui_state
            .switchbar
            .items
            .iter()
            .all(|item| item.rect.width == 90),
        "{:?}",
        ui_state.switchbar
    );
    assert_eq!(ui_state.status_bar.text, "options saved");
    let ini = fs::read_to_string(settings_file_path(&local_app_data))?;
    for line in [
        "[timestamp]\r\nshow=off\r\nformat=[HH:nn:ss]\r\n",
        "[connect]\r\nstartup=off\r\n",
        "buttons=90\r\n",
        "[other]\r\nbuffer=20000\r\n",
    ] {
        assert!(ini.contains(line), "{line:?} in {ini:?}");
    }

    // The menu item opens it too, with what was saved.
    let menu_thread = open_options_from_menu(&app);
    let dialog = wait_for_options_dialog(&app)?;
    assert_eq!(
        unsafe { read_window_text(GetDlgItem(dialog, OPTIONS_SWITCHBAR_BUTTONS_ID)) },
        "90"
    );
    post_options_command(dialog, IDCANCEL)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn options_logging_page_saves_and_new_windows_follow_it() -> Result<(), Box<dyn std::error::Error>>
{
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    app.open_dialog(AutomationDialog::Options)?;
    let dialog = wait_for_options_dialog(&app)?;
    app.select_options_page("Chat/Logging")?;
    let options = app
        .dump_ui_state()?
        .options_dialog
        .expect("the dialog is open");
    assert_eq!(
        options.visible_controls,
        [
            OPTIONS_LOG_ROOMS_ID as u16,
            OPTIONS_LOG_DIRECT_ID as u16,
            OPTIONS_LOG_TIMESTAMP_ID as u16,
            OPTIONS_LOG_FOLDER_ID as u16,
        ]
    );
    assert_eq!(
        options.logging,
        UiLoggingOptions {
            rooms: false,
            direct: false,
            timestamp: true,
        }
    );
    assert_eq!(
        unsafe { read_window_text(GetDlgItem(dialog, OPTIONS_LOG_FOLDER_ID)) },
        r"Folder: %LOCALAPPDATA%\mirx\ui-shell\logs"
    );
    unsafe {
        set_options_check(dialog, OPTIONS_LOG_DIRECT_ID, true);
        set_options_check(dialog, OPTIONS_LOG_TIMESTAMP_ID, false);
    }
    assert_eq!(
        app.dump_ui_state()?
            .options_dialog
            .expect("the dialog is open")
            .logging,
        UiLoggingOptions {
            rooms: false,
            direct: true,
            timestamp: false,
        }
    );
    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    app.wait_idle(Duration::from_secs(5))?;
    assert!(
        fs::read_to_string(settings_file_path(&local_app_data))?
            .contains("[logging]\r\nrooms=off\r\ndirect=on\r\ntimestamp=off\r\n")
    );
    // Windows already open have decided; a query that opens now logs.
    assert_eq!(view_log(&app, &room_identity("!alpha:example"))?, None);
    let mut carol = room_summary("!carol:example", "Carol", false);
    carol.is_direct = true;
    carol.direct_user_ids = vec!["@carol:example".to_owned()];
    let mut rooms = close_lifecycle_rooms();
    rooms.push(carol);
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::SyncedRooms(rooms)])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert!(view_log(&app, &room_identity("!carol:example"))?.is_some());
    app.append_synthetic_events(&serde_json::to_string(&vec![text_event(
        "!carol:example",
        "@carol:example",
        now_ms(),
        "carol news",
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    // Without timestamps.
    let log = read_log(&log_file_path(&local_app_data, "@carol.example"))?;
    assert_eq!(log[2..], ["<@carol:example> carol news".to_owned()]);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn options_chat_page_saves_its_options() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let chat_options = |app: &MirxApp| -> Result<UiOptionsDialog, Box<dyn std::error::Error>> {
        Ok(app
            .dump_ui_state()?
            .options_dialog
            .expect("the dialog is open"))
    };
    app.open_dialog(AutomationDialog::Options)?;
    let dialog = wait_for_options_dialog(&app)?;
    app.select_options_page("Chat")?;
    let options = chat_options(&app)?;
    assert_eq!(options.selected, "Chat");
    assert_eq!(
        options.visible_controls,
        [
            OPTIONS_CHAT_RANK_PREFIX_ID as u16,
            OPTIONS_CHAT_JOIN_ON_INVITE_ID as u16,
            OPTIONS_CHAT_ACTIVE_AWAY_ID as u16,
            OPTIONS_CHAT_ACTIVE_INVITES_ID as u16,
            OPTIONS_CHAT_ACTIVE_WHOIS_ID as u16,
        ]
    );
    assert_eq!(
        options.chat,
        UiChatOptions {
            rank_prefix: false,
            join_on_invite: false,
            active_away: true,
            active_invites: true,
            active_whois: true,
        }
    );
    let toggled = UiChatOptions {
        rank_prefix: true,
        join_on_invite: true,
        active_away: false,
        active_invites: false,
        active_whois: false,
    };
    unsafe {
        set_options_check(dialog, OPTIONS_CHAT_RANK_PREFIX_ID, true);
        set_options_check(dialog, OPTIONS_CHAT_JOIN_ON_INVITE_ID, true);
        set_options_check(dialog, OPTIONS_CHAT_ACTIVE_AWAY_ID, false);
        set_options_check(dialog, OPTIONS_CHAT_ACTIVE_INVITES_ID, false);
        set_options_check(dialog, OPTIONS_CHAT_ACTIVE_WHOIS_ID, false);
    }
    assert_eq!(chat_options(&app)?.chat, toggled);
    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    app.wait_idle(Duration::from_secs(5))?;
    assert!(
        fs::read_to_string(settings_file_path(&local_app_data))?.contains(
            "[chat]\r\nrank_prefix=on\r\njoin_on_invite=on\r\n\
             active_away=off\r\nactive_invites=off\r\nactive_whois=off\r\n"
        )
    );

    app.open_dialog(AutomationDialog::Options)?;
    let dialog = wait_for_options_dialog(&app)?;
    assert_eq!(chat_options(&app)?.chat, toggled);
    close_dialog(&app, dialog)?;

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn options_tray_and_tips_pages_save_and_apply() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    assert_eq!(tray_icon_and_hidden(&app)?, (false, false));
    app.open_dialog(AutomationDialog::Options)?;
    let dialog = wait_for_options_dialog(&app)?;
    let options = |app: &MirxApp| -> Result<UiOptionsDialog, Box<dyn std::error::Error>> {
        Ok(app
            .dump_ui_state()?
            .options_dialog
            .expect("the dialog is open"))
    };
    app.select_options_page("Display/Tray")?;
    let tray = options(&app)?;
    assert_eq!(tray.selected, "Display/Tray");
    assert_eq!(
        tray.visible_controls,
        [
            OPTIONS_TRAY_ALWAYS_ID as u16,
            OPTIONS_TRAY_STARTUP_ID as u16,
            OPTIONS_TRAY_MINIMIZE_ID as u16,
            OPTIONS_TRAY_SINGLE_CLICK_ID as u16,
        ]
    );
    assert_eq!(
        tray.tray,
        UiTrayOptions {
            always: false,
            startup: false,
            minimize: false,
            single_click: false,
        }
    );
    unsafe {
        set_options_check(dialog, OPTIONS_TRAY_ALWAYS_ID, true);
        set_options_check(dialog, OPTIONS_TRAY_SINGLE_CLICK_ID, true);
    }

    app.select_options_page("Display/Tips")?;
    let tips = options(&app)?;
    assert_eq!(
        tips.visible_controls,
        [
            OPTIONS_TIPS_HIGHLIGHTS_ID as u16,
            OPTIONS_TIPS_DIRECT_ID as u16,
            OPTIONS_TIPS_ROOMS_ID as u16,
            OPTIONS_TIPS_NOTE_ID as u16,
        ]
    );
    assert_eq!(
        tips.tips,
        UiTipsOptions {
            highlights: true,
            direct: true,
            rooms: false,
        }
    );
    unsafe {
        set_options_check(dialog, OPTIONS_TIPS_DIRECT_ID, false);
        set_options_check(dialog, OPTIONS_TIPS_ROOMS_ID, true);
    }
    let edited = options(&app)?;
    assert_eq!(
        (edited.tray, edited.tips),
        (
            UiTrayOptions {
                always: true,
                startup: false,
                minimize: false,
                single_click: true,
            },
            UiTipsOptions {
                highlights: true,
                direct: false,
                rooms: true,
            }
        )
    );

    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    // Always shows the icon at once, with mirx still on screen. Adding it
    // sends to the shell, which answers our dumps meanwhile: wait for the
    // icon, not for idle.
    wait_for_tray_icon(&app, true)?;
    assert!(!tray_icon_and_hidden(&app)?.1);
    assert!(
        fs::read_to_string(settings_file_path(&local_app_data))?.contains(
            "[tray]\r\nalways=on\r\nstartup=off\r\nminimize=off\r\nsingle_click=on\r\n\
             [tips]\r\nhighlights=on\r\ndirect=off\r\nrooms=on\r\n"
        )
    );

    // And turning it off removes the icon again.
    app.open_dialog(AutomationDialog::Options)?;
    let dialog = wait_for_options_dialog(&app)?;
    app.select_options_page("Display/Tray")?;
    assert!(options(&app)?.tray.always);
    unsafe { set_options_check(dialog, OPTIONS_TRAY_ALWAYS_ID, false) };
    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    wait_for_tray_icon(&app, false)?;
    assert!(!status_view_contains(&app, "Tray icon unavailable")?);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn options_display_activity_colours_recolour_the_switchbar()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    assert_eq!(
        app.dump_ui_state()?.colors.switchbar,
        UiActivityColors {
            event: 5,
            message: 4,
            highlight: 12,
        }
    );
    let menu_thread = open_options_from_menu(&app);
    let dialog = wait_for_options_dialog(&app)?;
    app.select_options_page("Display")?;
    let options = app
        .dump_ui_state()?
        .options_dialog
        .expect("the dialog is open");
    assert_eq!(
        options.activity_colors,
        UiActivityColors {
            event: 5,
            message: 4,
            highlight: 12,
        }
    );
    // Picking from a drop-down, as the keyboard or the list does.
    for (id, index) in OPTIONS_ACTIVITY_COLOR_IDS.into_iter().zip([3, 9, 13]) {
        unsafe { SendMessageW(GetDlgItem(dialog, id), CB_SETCURSEL, index, 0) };
    }
    let picked = UiActivityColors {
        event: 3,
        message: 9,
        highlight: 13,
    };
    assert_eq!(
        app.dump_ui_state()?
            .options_dialog
            .expect("the dialog is open")
            .activity_colors,
        picked
    );
    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");
    app.wait_idle(Duration::from_secs(5))?;

    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.colors.switchbar, picked);
    assert_eq!(ui_state.status_bar.text, "options saved");
    let ini = fs::read_to_string(settings_file_path(&local_app_data))?;
    assert!(
        ini.contains("event=3\r\nmessage=9\r\nhighlight=13\r\n"),
        "{ini:?}"
    );
    drop(app);

    let (app, _) = launch_close_lifecycle_app_in(local_app_data.clone())?;
    assert_eq!(app.dump_ui_state()?.colors.switchbar, picked);
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn options_dialog_rejects_a_bad_field_and_cancel_changes_nothing()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let before = app.dump_ui_state()?;
    let menu_thread = open_options_from_menu(&app);
    let dialog = wait_for_options_dialog(&app)?;
    unsafe { set_options_text(dialog, OPTIONS_SWITCHBAR_BUTTONS_ID, "20") };
    post_options_command(dialog, IDOK)?;
    let (message_box, text) = wait_for_owned_message_box(dialog);
    assert_eq!(text, "Switchbar buttons must be 40-400");
    assert_eq!(unsafe { read_window_text(message_box) }, "mirx Options");
    // The dialog shows the wrong field's page.
    let options = app
        .dump_ui_state()?
        .options_dialog
        .expect("the dialog stays open");
    assert_eq!(options.selected, "Display");
    assert_eq!(
        options.visible_controls,
        [
            OPTIONS_SWITCHBAR_BUTTONS_ID as u16,
            OPTIONS_ACTIVITY_COLOR_IDS[0] as u16,
            OPTIONS_ACTIVITY_COLOR_IDS[1] as u16,
            OPTIONS_ACTIVITY_COLOR_IDS[2] as u16,
            OPTIONS_MARKER_SHOW_ID as u16,
            OPTIONS_MARKER_COLOR_ID as u16,
        ]
    );
    answer_message_box(&app, message_box, IDOK)?;
    assert_ne!(unsafe { IsWindow(dialog) }, 0);
    assert!(!settings_file_path(&local_app_data).exists());

    post_options_command(dialog, IDCANCEL)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");

    // Esc in a field cancels too.
    let menu_thread = open_options_from_menu(&app);
    let dialog = wait_for_options_dialog(&app)?;
    let format = unsafe { GetDlgItem(dialog, OPTIONS_TIMESTAMP_FORMAT_ID) };
    unsafe { set_options_text(dialog, OPTIONS_TIMESTAMP_FORMAT_ID, "") };
    assert_ne!(
        unsafe { PostMessageW(format, WM_KEYDOWN, VK_ESCAPE as WPARAM, 0) },
        0
    );
    wait_for_window_gone(dialog, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");
    app.wait_idle(Duration::from_secs(5))?;

    let after = app.dump_ui_state()?;
    assert_eq!(after.timestamp, before.timestamp);
    assert_eq!(after.switchbar, before.switchbar);
    assert!(!settings_file_path(&local_app_data).exists());
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// The Connect page's reconnect and retry controls save to `[connect]`;
/// Retry and Delay grey with Enable connect retry, and a wrong one
/// brings its page back with the error.
#[test]
fn options_connect_page_saves_reconnect_and_retry() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let menu_thread = open_options_from_menu(&app);
    let dialog = wait_for_options_dialog(&app)?;
    let connect_options =
        |app: &GuiTestApp| -> Result<UiConnectOptions, Box<dyn std::error::Error>> {
            Ok(app
                .dump_ui_state()?
                .options_dialog
                .ok_or("the dialog is open")?
                .connect)
        };
    assert_eq!(
        connect_options(&app)?,
        UiConnectOptions {
            startup: true,
            reconnect: true,
            retry: true,
            retry_times: "99".to_owned(),
            retry_delay: "10".to_owned(),
            retry_fields_enabled: true,
            perform_enabled: false,
            perform_lines: Vec::new(),
        }
    );

    // Clicking Enable connect retry greys Retry and Delay, and again
    // ungreys them.
    let retry = unsafe { GetDlgItem(dialog, OPTIONS_RETRY_ID) };
    unsafe { SendMessageW(retry, BM_CLICK, 0, 0) };
    let options = connect_options(&app)?;
    assert!(
        !options.retry && !options.retry_fields_enabled,
        "{options:?}"
    );
    unsafe { SendMessageW(retry, BM_CLICK, 0, 0) };
    let options = connect_options(&app)?;
    assert!(options.retry && options.retry_fields_enabled, "{options:?}");

    unsafe {
        set_options_check(dialog, OPTIONS_RECONNECT_ID, false);
        set_options_text(dialog, OPTIONS_RETRY_TIMES_ID, "5");
        set_options_text(dialog, OPTIONS_RETRY_DELAY_ID, "0");
    }
    app.select_options_page("Chat/Messages")?;
    post_options_command(dialog, IDOK)?;
    let (message_box, text) = wait_for_owned_message_box(dialog);
    assert_eq!(text, "Connect retry_delay must be 1-3600");
    let options = app
        .dump_ui_state()?
        .options_dialog
        .expect("the dialog stays open");
    assert_eq!(options.selected, "Connect/Options");
    answer_message_box(&app, message_box, IDOK)?;
    assert!(!settings_file_path(&local_app_data).exists());

    unsafe { set_options_text(dialog, OPTIONS_RETRY_DELAY_ID, "30") };
    post_options_command(dialog, IDOK)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");
    app.wait_idle(Duration::from_secs(5))?;
    let ini = fs::read_to_string(settings_file_path(&local_app_data))?;
    let connect = "[connect]\r\nstartup=on\r\nreconnect=off\r\nretry=on\r\nretry_times=5\r\nretry_delay=30\r\n";
    assert!(ini.contains(connect), "{connect:?} in {ini:?}");

    // The dialog opens with what was saved.
    let menu_thread = open_options_from_menu(&app);
    let dialog = wait_for_options_dialog(&app)?;
    assert_eq!(
        connect_options(&app)?,
        UiConnectOptions {
            startup: true,
            reconnect: false,
            retry: true,
            retry_times: "5".to_owned(),
            retry_delay: "30".to_owned(),
            retry_fields_enabled: true,
            perform_enabled: false,
            perform_lines: Vec::new(),
        }
    );
    post_options_command(dialog, IDCANCEL)?;
    wait_for_window_gone(dialog, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

const PERFORM_DIALOG_ENABLED_ID: i32 = 6150;
const PERFORM_DIALOG_EDIT_ID: i32 = 6151;
const PERFORM_DIALOG_OK_ID: WPARAM = 6152;
const PERFORM_DIALOG_CANCEL_ID: WPARAM = 6153;

/// Perform... on the open Options dialog `options`: the Perform dialog,
/// owned by it.
fn open_perform_dialog(options: HWND) -> Result<HWND, Box<dyn std::error::Error>> {
    post_dialog_command(options, OPTIONS_PERFORM_ID as WPARAM);
    let dialog = wait_for_window(&wide_null("mirxWin32PerformDialog"), "Perform dialog")?;
    assert_eq!(unsafe { read_window_text(dialog) }, "Perform");
    assert_eq!(unsafe { GetWindow(dialog, GW_OWNER) }, options);
    Ok(dialog)
}

fn perform_dialog_enabled(dialog: HWND) -> bool {
    // BM_GETCHECK: BST_CHECKED is 1.
    unsafe { SendMessageW(GetDlgItem(dialog, PERFORM_DIALOG_ENABLED_ID), 0x00F0, 0, 0) == 1 }
}

/// The Perform dialog edits what the Options dialog's OK saves: its OK
/// hands the checked lines to the form, a wrong line keeps it open with
/// that line selected, and Options' Cancel drops its edits too.
#[test]
fn options_perform_dialog_edits_what_options_ok_saves() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let menu_thread = open_options_from_menu(&app);
    let options = wait_for_options_dialog(&app)?;
    let connect_options =
        |app: &GuiTestApp| -> Result<UiConnectOptions, Box<dyn std::error::Error>> {
            Ok(app
                .dump_ui_state()?
                .options_dialog
                .ok_or("the dialog is open")?
                .connect)
        };
    let perform = open_perform_dialog(options)?;
    assert!(!perform_dialog_enabled(perform));
    let edit = unsafe { GetDlgItem(perform, PERFORM_DIALOG_EDIT_ID) };
    assert_eq!(unsafe { read_window_text(edit) }, "");
    unsafe {
        set_options_check(perform, PERFORM_DIALOG_ENABLED_ID, true);
        set_options_text(
            perform,
            PERFORM_DIALOG_EDIT_ID,
            "join #a:example\r\n\r\n  msg @b:example hi | echo -s x  ",
        );
    }
    accept_address_entry(&app, perform, PERFORM_DIALOG_OK_ID)?;
    let connect = connect_options(&app)?;
    assert!(connect.perform_enabled);
    assert_eq!(
        connect.perform_lines,
        ["join #a:example", "msg @b:example hi | echo -s x"]
    );
    assert!(!settings_file_path(&local_app_data).exists());
    post_options_command(options, IDOK)?;
    wait_for_window_gone(options, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");
    app.wait_idle(Duration::from_secs(5))?;
    let saved = "[perform]\r\nenabled=on\r\nn0=join #a:example\r\n\
                 n1=msg @b:example hi | echo -s x\r\n";
    let ini = fs::read_to_string(settings_file_path(&local_app_data))?;
    assert!(ini.ends_with(saved), "{ini}");

    // Reopened, it shows what was saved; a wrong line is refused and
    // selected, and the dialog stays open.
    let menu_thread = open_options_from_menu(&app);
    let options = wait_for_options_dialog(&app)?;
    let perform = open_perform_dialog(options)?;
    assert!(perform_dialog_enabled(perform));
    let edit = unsafe { GetDlgItem(perform, PERFORM_DIALOG_EDIT_ID) };
    assert_eq!(
        unsafe { read_window_text(edit) },
        "join #a:example\r\nmsg @b:example hi | echo -s x"
    );
    unsafe { set_options_text(perform, PERFORM_DIALOG_EDIT_ID, "join #a\r\n{ x") };
    post_dialog_command(perform, PERFORM_DIALOG_OK_ID);
    let (message_box, text) = wait_for_owned_message_box(perform);
    assert_eq!(
        text,
        "Line 2: nested blocks need a scripting language, which mirx does not have"
    );
    answer_message_box(&app, message_box, IDOK)?;
    assert_eq!(unsafe { IsWindow(perform) }, 1);
    assert_eq!(edit_selection(edit), (9, 12));

    // Cleared and unchecked, then Options' Cancel: nothing is saved.
    unsafe {
        set_options_check(perform, PERFORM_DIALOG_ENABLED_ID, false);
        set_options_text(perform, PERFORM_DIALOG_EDIT_ID, "");
    }
    accept_address_entry(&app, perform, PERFORM_DIALOG_OK_ID)?;
    let connect = connect_options(&app)?;
    assert!(!connect.perform_enabled && connect.perform_lines.is_empty());
    post_options_command(options, IDCANCEL)?;
    wait_for_window_gone(options, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(
        fs::read_to_string(settings_file_path(&local_app_data))?,
        ini
    );

    // Its Cancel drops its own edits.
    let menu_thread = open_options_from_menu(&app);
    let options = wait_for_options_dialog(&app)?;
    let perform = open_perform_dialog(options)?;
    unsafe { set_options_check(perform, PERFORM_DIALOG_ENABLED_ID, false) };
    post_dialog_command(perform, PERFORM_DIALOG_CANCEL_ID);
    wait_for_window_gone(perform, "Perform dialog")?;
    assert!(connect_options(&app)?.perform_enabled);
    post_options_command(options, IDCANCEL)?;
    wait_for_window_gone(options, "Options dialog")?;
    menu_thread.join().expect("the menu thread must not panic");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

const ALIASES_DIALOG_EDIT_ID: i32 = 5030;
const ALIASES_DIALOG_OK_ID: WPARAM = 5031;
const ALIASES_DIALOG_CANCEL_ID: WPARAM = 5032;

fn wait_for_aliases_dialog() -> Result<HWND, Box<dyn std::error::Error>> {
    let dialog = wait_for_window(&wide_null("mirxWin32AliasesDialog"), "Aliases dialog")?;
    assert_eq!(unsafe { read_window_text(dialog) }, "Aliases - aliases.ini");
    Ok(dialog)
}

/// The editbox's selection, start and end.
fn edit_selection(edit: HWND) -> (usize, usize) {
    let selection = unsafe { SendMessageW(edit, EM_GETSEL, 0, 0) } as usize;
    (selection & 0xffff, selection >> 16)
}

#[test]
fn aliases_dialog_edits_aliases_ini() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_close_lifecycle_app()?;
    let aliases_ini = local_app_data
        .join("mirx")
        .join("ui-shell")
        .join("aliases.ini");
    let defaults = app.dump_ui_state()?.aliases;
    assert_eq!(defaults.len(), 8);

    // Alt+A, as mIRC's Scripts Editor at its Aliases tab.
    let frame = app.automation_frame_hwnd() as HWND;
    unsafe { SetForegroundWindow(frame) };
    press_keys(&[VK_MENU, u16::from(b'A')]);
    let dialog = wait_for_aliases_dialog()?;
    let edit = unsafe { GetDlgItem(dialog, ALIASES_DIALOG_EDIT_ID) };
    assert_eq!(unsafe { read_window_text(edit) }, defaults.join("\r\n"));
    wait_for_dialog_focus(&app, dialog, ALIASES_DIALOG_EDIT_ID)?;
    assert_eq!(edit_selection(edit), (0, 0));
    // Enter is a line break, Tab goes on to OK.
    for key in [VK_RETURN, VK_TAB] {
        assert_ne!(
            unsafe { PostMessageW(edit, WM_KEYDOWN, key as WPARAM, 0) },
            0
        );
    }
    wait_for_dialog_focus(&app, dialog, ALIASES_DIALOG_OK_ID as i32)?;
    assert_eq!(
        unsafe { read_window_text(edit) },
        format!("\r\n{}", defaults.join("\r\n"))
    );

    // A wrong line keeps the dialog open, and is selected.
    let set_text = |text: &str| {
        let text = wide_null(text);
        unsafe { SendMessageW(edit, WM_SETTEXT, 0, text.as_ptr() as isize) };
    };
    set_text("; mine\r\n/x {\r\nsay a");
    assert_ne!(
        unsafe { PostMessageW(dialog, WM_COMMAND, ALIASES_DIALOG_OK_ID, 0) },
        0
    );
    let (message_box, text) = wait_for_owned_message_box(dialog);
    assert_eq!(text, "Line 2: /x's block has no }");
    answer_message_box(&app, message_box, IDOK)?;
    assert_eq!(unsafe { IsWindow(dialog) }, 1);
    assert_eq!(edit_selection(edit), (8, 12));
    assert!(!aliases_ini.exists());

    let lines = ["; mine", "/hi say hello $1", "/two {", "  say a", "}"];
    set_text(&lines.join("\r\n"));
    assert_ne!(
        unsafe { PostMessageW(dialog, WM_COMMAND, ALIASES_DIALOG_OK_ID, 0) },
        0
    );
    wait_for_window_gone(dialog, "Aliases dialog")?;
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.aliases, lines);
    assert_eq!(ui_state.status_bar.text, "aliases saved");
    assert_eq!(
        fs::read_to_string(&aliases_ini)?,
        "[aliases]\r\nn0=; mine\r\nn1=/hi say hello $1\r\nn2=/two {\r\nn3=  say a\r\nn4=}\r\n"
    );

    // Esc in the editbox, and Cancel, change nothing.
    for close in ["escape", "cancel"] {
        app.open_dialog(AutomationDialog::Aliases)?;
        let dialog = wait_for_aliases_dialog()?;
        let edit = unsafe { GetDlgItem(dialog, ALIASES_DIALOG_EDIT_ID) };
        assert_eq!(unsafe { read_window_text(edit) }, lines.join("\r\n"));
        let junk = wide_null("/junk");
        unsafe { SendMessageW(edit, WM_SETTEXT, 0, junk.as_ptr() as isize) };
        let posted = match close {
            "escape" => unsafe { PostMessageW(edit, WM_KEYDOWN, VK_ESCAPE as WPARAM, 0) },
            _ => unsafe { PostMessageW(dialog, WM_COMMAND, ALIASES_DIALOG_CANCEL_ID, 0) },
        };
        assert_ne!(posted, 0);
        wait_for_window_gone(dialog, "Aliases dialog")?;
        app.wait_idle(Duration::from_secs(5))?;
        assert_eq!(app.dump_ui_state()?.aliases, lines, "{close}");
    }

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

