#[test]
fn automation_driver_slash_part_thread_targets_parent_and_removes_stale_thread()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let args = [OsString::from("--automation")];
    let fixture_path = fixture_state_path("thread-hierarchy.json");

    let app = launch_app_with_options(&exe_path, &args, options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&fs::read_to_string(&fixture_path)?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let thread_view_identity = thread_identity("!ops:example", "$thread-root");
    app.select_view(thread_view_identity.clone())?;

    app.set_compose_text("/part")?;
    app.send_compose_key(ComposeKey::Return)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(app.compose_text()?, "");

    let model = app.dump_model()?;
    assert_eq!(model.status, "part submitted: !ops:example");
    assert_eq!(
        model.submitted_membership_commands,
        vec![SubmittedMembershipCommand {
            action: MembershipCommandAction::Leave,
            target: "!ops:example".to_owned(),
        }]
    );
    assert_eq!(app.dump_ui_state()?.mdi.active, thread_view_identity);

    app.load_events(&serde_json::to_string(&vec![
        Event::Started,
        Event::SyncedRooms(vec![room_summary("!alpha:example", "Alpha", false)]),
        text_event(
            "!alpha:example",
            "@alice:example",
            1_700_000_180_000,
            "alpha after thread part",
        ),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let replaced_model = app.dump_model()?;
    assert_eq!(
        replaced_model
            .rooms
            .iter()
            .map(|room| room.room_id.as_str())
            .collect::<Vec<_>>(),
        vec!["!alpha:example"]
    );
    let replaced_state = app.dump_ui_state()?;
    assert_eq!(replaced_state.mdi.active, room_identity("!alpha:example"));
    assert_active_switchbar_item(&replaced_state, &room_identity("!alpha:example"));
    assert!(
        replaced_state
            .mdi
            .views
            .iter()
            .all(|view| view.identity != room_identity("!ops:example")
                && view.identity != thread_identity("!ops:example", "$thread-root"))
    );
    assert!(
        replaced_state
            .switchbar
            .items
            .iter()
            .all(|item| item.identity != room_identity("!ops:example")
                && item.identity != thread_identity("!ops:example", "$thread-root"))
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn automation_driver_slash_topic_records_submission_and_waits_for_inbound_topic_event()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let args = [OsString::from("--automation")];

    let app = launch_app_with_options(&exe_path, &args, options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let before = app.room_activity(Some("!beta:example"))?;
    assert!(app.dump_model()?.submitted_room_topic_commands.is_empty());

    app.set_compose_text("/topic incident review")?;
    app.send_compose_key(ComposeKey::Return)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(app.compose_text()?, "");

    let model = app.dump_model()?;
    assert_eq!(model.status, "topic change submitted for !beta:example");
    assert_eq!(
        model.submitted_room_topic_commands,
        vec![SubmittedRoomTopicCommand {
            room_id: "!beta:example".to_owned(),
            topic: "incident review".to_owned(),
        }]
    );
    assert_eq!(app.room_activity(Some("!beta:example"))?, before);

    let before_topic_state = app.dump_ui_state()?;
    let beta_view = find_view(&before_topic_state, &room_identity("!beta:example"));
    assert!(!view_contains(beta_view, "* Topic is 'incident review'"));
    assert!(!view_contains(
        beta_view,
        "[22:16] * @alice:example changes topic to 'incident review'"
    ));

    app.append_synthetic_events(&serde_json::to_string(&vec![topic_event_with_event_id(
        "!beta:example",
        "$beta-topic-1",
        "@alice:example",
        1_700_000_180_000,
        "incident review",
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    assert_eq!(
        app.room_activity(Some("!beta:example"))?,
        vec![
            text_entry(
                "!beta:example",
                "@bob:example",
                1_700_000_060_000,
                "beta first",
            ),
            text_entry(
                "!beta:example",
                "@bob:example",
                1_700_000_120_000,
                "beta second",
            ),
            topic_entry_with_event_id(
                "!beta:example",
                "$beta-topic-1",
                "@alice:example",
                1_700_000_180_000,
                "incident review",
            ),
        ]
    );

    let after_topic_state = app.dump_ui_state()?;
    let beta_view = find_view(&after_topic_state, &room_identity("!beta:example"));
    assert!(view_contains(beta_view, "* Topic is 'incident review'"));
    assert!(view_contains(
        beta_view,
        "[22:16] * @alice:example changes topic to 'incident review'"
    ));

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn slash_topic_shows_and_names_rooms_by_alias() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    let mut beta = room_summary("!beta:example", "Beta", true);
    beta.topic = Some("incident review".to_owned());
    beta.canonical_alias = Some("#beta:example".to_owned());
    let mut lobby = room_summary("!lobby:example", "Lobby", false);
    lobby.canonical_alias = Some("#lobby:example".to_owned());
    lobby.alt_aliases = vec!["#hall:example".to_owned()];
    app.load_events(&serde_json::to_string(&vec![
        Event::Started,
        Event::SyncedRooms(vec![beta, lobby]),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;

    type_commands(
        &app,
        &[
            "/topic",
            "/topic #hall",
            "/topic #lobby:example deploy at noon",
            "/topic #nope x",
            "/msg #lobby see ops",
        ],
    )?;

    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, beta);
    let view = find_view(&ui_state, &beta);
    // The window's own topic line, then /topic's.
    assert_eq!(
        view_lines_containing(view, "* Topic is 'incident review'").len(),
        2,
        "{:?}",
        view.lines
    );
    for line in [
        "] * No topic is set",
        "] * /topic: unknown room: #nope",
        "] -> *#lobby* see ops",
    ] {
        assert!(
            only_view_line_containing(view, line).ends_with(line),
            "{line:?} in {:?}",
            view.lines
        );
    }
    assert_eq!(
        app.dump_model()?.submitted_room_topic_commands,
        vec![SubmittedRoomTopicCommand {
            room_id: "!lobby:example".to_owned(),
            topic: "deploy at noon".to_owned(),
        }]
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn slash_ignore_round_trip() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    let mut events = base_events();
    events.insert(
        1,
        Event::LoggedIn {
            session: core_stored_session(),
            homeserver_url: "https://matrix.example/".to_owned(),
        },
    );
    events.push(room_members_event(
        "!beta:example",
        &[("@alice:example", "Alice"), ("@bob:example", "Bob")],
    ));
    app.load_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;

    type_commands(&app, &["/ignore"])?;
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::IgnoredUsers(
        Vec::new(),
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    type_commands(&app, &["/ignore", "/ignore Bob", "/ignore Alice"])?;
    assert_eq!(
        app.dump_model()?.submitted_user_commands,
        vec![SubmittedUserCommand {
            action: UserCommandAction::Ignore,
            user_id: "@bob:example".to_owned(),
        }]
    );

    // The server's echo confirms the change.
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::IgnoredUsers(vec![
        "@bob:example".to_owned(),
    ])])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(
        app.dump_ui_state()?.ignored_users,
        Some(vec!["@bob:example".to_owned()])
    );
    type_commands(&app, &["/ignore", "/ignore Bob", "/unignore Bob"])?;
    assert_eq!(
        app.dump_model()?.submitted_user_commands[1..],
        [SubmittedUserCommand {
            action: UserCommandAction::Unignore,
            user_id: "@bob:example".to_owned(),
        }]
    );

    let ui_state = app.dump_ui_state()?;
    let view = find_view(&ui_state, &beta);
    for line in [
        "] * /ignore: the ignore list has not been received yet",
        "] * Ignore list is empty",
        "] * /ignore: you cannot ignore yourself",
        "] * Added Bob (@bob:example) to ignore list",
        "] * Ignore list:",
        "] *   Bob (@bob:example)",
        "] * /ignore: Bob is already ignored",
    ] {
        assert!(
            only_view_line_containing(view, line).ends_with(line),
            "{line:?} in {:?}",
            view.lines
        );
    }

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn slash_whois_prints_server_profile() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;

    // Not a member of any known room: only the server knows them.
    type_commands(&app, &["/whois @stranger:remote"])?;
    // The automation core, which is not signed in, refuses it with an
    // error of its own; the UserProfile below stands in for the answer.
    assert_eq!(
        app.dump_model()?.submitted_user_commands,
        vec![SubmittedUserCommand {
            action: UserCommandAction::FetchProfile,
            user_id: "@stranger:remote".to_owned(),
        }]
    );

    app.append_synthetic_events(&serde_json::to_string(&vec![
        Event::UserProfile(UserProfile {
            user_id: "@stranger:remote".to_owned(),
            display_name: Some("Stranger".to_owned()),
            presence: None,
        }),
        Event::Error(mirx_core::CoreErrorEvent {
            operation: mirx_core::Operation::FetchUserProfile,
            room_id: None,
            message: "no such user @nobody:remote".to_owned(),
        }),
        // Away and idle: IRC's 301 and 317, before the end.
        Event::UserProfile(UserProfile {
            user_id: "@lazy:remote".to_owned(),
            display_name: Some("Lazy".to_owned()),
            presence: Some(mirx_core::UserPresence {
                kind: mirx_core::PresenceKind::Unavailable,
                status_msg: Some("lunch".to_owned()),
                last_active_ago_ms: Some(3_725_000),
                currently_active: Some(false),
            }),
        }),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let ui_state = app.dump_ui_state()?;
    let view = find_view(&ui_state, &beta);
    for line in [
        "] * Stranger is @stranger:remote (Stranger)",
        "] * Stranger's homeserver is remote",
        "] * /whois: no such user @nobody:remote",
    ] {
        assert!(
            only_view_line_containing(view, line).ends_with(line),
            "{line:?} in {:?}",
            view.lines
        );
    }
    let lazy: Vec<_> = view_lines_containing(view, "* Lazy")
        .into_iter()
        .map(|line| line.split_once("] ").map_or(line, |(_, text)| text))
        .collect();
    assert_eq!(
        lazy,
        [
            "* Lazy is @lazy:remote (Lazy)",
            "* Lazy's homeserver is remote",
            "* Lazy is away: lunch",
            "* Lazy has been idle 1hr 2mins 5secs",
        ]
    );
    assert!(!view_contains(
        find_view(&ui_state, &ViewIdentity::Status),
        "Stranger"
    ));

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Away and offline members are grey in the nick list, and a message to
/// an away user's query says so once for each away status, as IRC's
/// `RPL_AWAY` does.
#[test]
fn away_members_are_grey_and_a_query_says_away_once() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    let mut events = base_events_with_a_query();
    events.push(room_members_event(
        "!beta:example",
        &[
            ("@alice:example", "Alice"),
            ("@bob:example", "Bob"),
            ("@carol:example", "Carol"),
        ],
    ));
    events.push(room_members_event(
        "!dm:example",
        &[("@alice:example", "Alice")],
    ));
    app.load_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let presence = |user_id: &str, kind, status_msg: Option<&str>| mirx_core::PresenceChange {
        user_id: user_id.to_owned(),
        kind,
        status_msg: status_msg.map(str::to_owned),
    };
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::PresenceChanged(
        vec![
            presence(
                "@alice:example",
                mirx_core::PresenceKind::Unavailable,
                Some("lunch"),
            ),
            presence("@bob:example", mirx_core::PresenceKind::Offline, None),
        ],
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let beta = room_identity("!beta:example");
    let ui_state = app.dump_ui_state()?;
    assert_eq!(
        find_view(&ui_state, &beta)
            .members
            .iter()
            .map(|member| (member.nick.as_str(), member.presence))
            .collect::<Vec<_>>(),
        [
            ("Alice", Some(mirx_core::PresenceKind::Unavailable)),
            ("Bob", Some(mirx_core::PresenceKind::Offline)),
            ("Carol", None),
        ]
    );

    // In the query, once; never in a channel.
    let dm = room_identity("!dm:example");
    app.select_view(dm.clone())?;
    type_commands(&app, &["hi", "still there?"])?;
    app.select_view(beta.clone())?;
    type_commands(&app, &["hi all"])?;
    // The unauthenticated core refuses the sends; the UI recorded them.
    assert_eq!(app.dump_model()?.submitted_message_commands.len(), 3);
    let lines = |ui_state: &UiState, view: &ViewIdentity, text: &str| {
        view_lines_containing(find_view(ui_state, view), text)
            .into_iter()
            .map(|line| {
                line.split_once("] ")
                    .map_or(line, |(_, text)| text)
                    .to_owned()
            })
            .collect::<Vec<_>>()
    };
    let ui_state = app.dump_ui_state()?;
    assert_eq!(lines(&ui_state, &dm, "is away"), ["* Alice is away: lunch"]);
    assert_eq!(lines(&ui_state, &beta, "is away"), Vec::<String>::new());

    // Back, then away with another message: said again, by `/msg` typed in
    // a channel, in the query (mIRC's Show in active: Away); then the
    // query has heard it.
    app.append_synthetic_events(&serde_json::to_string(&vec![
        Event::PresenceChanged(vec![presence(
            "@alice:example",
            mirx_core::PresenceKind::Online,
            None,
        )]),
        Event::PresenceChanged(vec![presence(
            "@alice:example",
            mirx_core::PresenceKind::Unavailable,
            Some("meeting"),
        )]),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    type_commands(&app, &["/msg Alice ping"])?;
    app.select_view(dm.clone())?;
    type_commands(&app, &["and now?"])?;
    assert_eq!(app.dump_model()?.submitted_message_commands.len(), 5);
    let ui_state = app.dump_ui_state()?;
    assert_eq!(lines(&ui_state, &beta, "Alice"), ["-> *Alice* ping"]);
    assert_eq!(
        lines(&ui_state, &dm, "is away"),
        ["* Alice is away: lunch", "* Alice is away: meeting"]
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn slash_away_marks_away_and_back() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;

    type_commands(&app, &["/away lunch", "/back", "/back x"])?;
    // The automation core, which is not signed in, refuses them; the
    // AwayChanged events below stand in for the server's answers.
    assert_eq!(
        app.dump_model()?.submitted_away_commands,
        vec![
            SubmittedAwayCommand {
                message: Some("lunch".to_owned()),
            },
            SubmittedAwayCommand { message: None },
        ]
    );
    let view = find_view(&app.dump_ui_state()?, &beta).clone();
    assert_eq!(
        view_lines_containing(&view, "* /away: ").len(),
        2,
        "{:?}",
        view.lines
    );
    assert!(only_view_line_containing(&view, "* /back:").ends_with("* /back: takes no parameters"));

    let changed = |message: Option<&str>, seen_as| {
        Event::AwayChanged(mirx_core::AwayChanged {
            message: message.map(str::to_owned),
            seen_as,
        })
    };
    app.append_synthetic_events(&serde_json::to_string(&vec![
        changed(Some("lunch"), mirx_core::PresenceKind::Unavailable),
        changed(Some("x"), mirx_core::PresenceKind::Offline),
        changed(None, mirx_core::PresenceKind::Online),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let ui_state = app.dump_ui_state()?;
    let view = find_view(&ui_state, &beta);
    let answers: Vec<_> = view
        .lines
        .iter()
        .filter(|line| line.contains("marked as being away") || line.contains("Others see"))
        .map(|line| {
            line.split_once("] ")
                .map_or(line.as_str(), |(_, text)| text)
        })
        .collect();
    assert_eq!(
        answers,
        [
            "* You have been marked as being away",
            "* You have been marked as being away",
            "* Others see you as offline: your server does not share presence",
            "* You are no longer marked as being away",
        ]
    );
    assert_eq!(
        ui_state.status_bar.text.split(" | ").next(),
        Some("back"),
        "{}",
        ui_state.status_bar.text
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// `base_events` with a query with Alice.
fn base_events_with_a_query() -> Vec<Event> {
    let mut events = base_events();
    events.insert(
        2,
        Event::SyncedRooms(vec![
            room_summary("!beta:example", "Beta", true),
            room_summary("!alpha:example", "Alpha", false),
            RoomSummary {
                is_direct: true,
                direct_user_ids: vec!["@alice:example".to_owned()],
                ..room_summary("!dm:example", "Alice", false)
            },
        ]),
    );
    events.push(text_event(
        "!dm:example",
        "@alice:example",
        1_700_000_180_000,
        "dm first",
    ));
    events
}

#[test]
fn amsg_ame_and_describe_send_to_channels_and_one_target() -> Result<(), Box<dyn std::error::Error>>
{
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events_with_a_query())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let alpha = room_identity("!alpha:example");
    app.select_view(alpha.clone())?;

    type_commands(&app, &["/amsg hi", "/ame waves", "/describe Beta nods"])?;
    let sent: Vec<_> = app
        .dump_model()?
        .submitted_message_commands
        .into_iter()
        .map(|command| (command.room_id, command.presentation, command.body))
        .collect();
    let text = RoomMessagePresentationKind::Text;
    let emote = RoomMessagePresentationKind::Emote;
    // The channels in window order (Beta first, as the switchbar shows
    // them), never the query.
    let channels = |presentation, body: &str| {
        ["!beta:example", "!alpha:example"]
            .map(|room_id| (room_id.to_owned(), presentation, body.to_owned()))
    };
    let mut expected = channels(text, "hi").to_vec();
    expected.extend(channels(emote, "waves"));
    expected.push(("!beta:example".to_owned(), emote, "nods".to_owned()));
    assert_eq!(sent, expected);
    // The unauthenticated core refuses the sends, in their rooms.
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert!(
        only_view_line_containing(find_view(&ui_state, &alpha), "-> Beta")
            .ends_with("-> Beta * nods")
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn typed_aliases_run_their_commands() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;
    let aliases_ini = local_app_data
        .join("mirx")
        .join("ui-shell")
        .join("aliases.ini");

    // mIRC's default aliases, with no aliases.ini.
    type_commands(&app, &["/j gamma:example", "/w @alice:example.org", "/w"])?;
    let model = app.dump_model()?;
    assert_eq!(
        model.submitted_membership_commands,
        [SubmittedMembershipCommand {
            action: MembershipCommandAction::Join,
            target: "#gamma:example".to_owned(),
        }]
    );
    assert_eq!(
        model
            .submitted_user_commands
            .iter()
            .map(|command| (command.action, command.user_id.as_str()))
            .collect::<Vec<_>>(),
        [(UserCommandAction::FetchProfile, "@alice:example.org")]
    );
    assert!(!aliases_ini.exists());

    type_commands(
        &app,
        &["/alias hi say hello $1 | say bye", "/hi there", "/!j x"],
    )?;
    let sent: Vec<_> = app
        .dump_model()?
        .submitted_message_commands
        .into_iter()
        .map(|command| (command.room_id, command.body))
        .collect();
    assert_eq!(
        sent,
        [
            ("!beta:example".to_owned(), "hello there".to_owned()),
            ("!beta:example".to_owned(), "bye".to_owned()),
        ]
    );
    let ui_state = app.dump_ui_state()?;
    assert_eq!(
        ui_state.aliases.last().map(String::as_str),
        Some("/hi say hello $1 | say bye")
    );
    assert_eq!(ui_state.aliases.len(), 9);
    assert!(
        only_view_line_containing(find_view(&ui_state, &beta), "/j:")
            .ends_with("] * /j: unknown command")
    );
    let ini = fs::read_to_string(&aliases_ini)?;
    assert!(
        ini.starts_with("[aliases]\r\nn0=/dop /deop $$1\r\n"),
        "{ini:?}"
    );
    assert!(
        ini.ends_with("n7=/s /server $$1\r\nn8=/hi say hello $1 | say bye\r\n"),
        "{ini:?}"
    );

    type_commands(&app, &["/alias hi", "/hi"])?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.aliases.len(), 8);
    assert!(
        only_view_line_containing(find_view(&ui_state, &beta), "/hi:")
            .ends_with("] * /hi: unknown command")
    );
    assert!(!fs::read_to_string(&aliases_ini)?.contains("/hi"));

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

