#[test]
fn echo_prints_where_it_is_told() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let (alpha, beta) = (
        room_identity("!alpha:example"),
        room_identity("!beta:example"),
    );
    // Alpha's message is read: the echo alone colours its button.
    app.select_view(alpha.clone())?;
    app.select_view(beta.clone())?;

    type_commands(
        &app,
        &[
            "/echo plain",
            "/echo 4 -t red",
            "/alias said say hi | echo -a said hi",
            "/said",
        ],
    )?;
    // The unauthenticated core refuses the send, with a line of its own.
    let timeline = active_timeline(&app)?;
    let line = |wanted: &dyn Fn(&str) -> bool| {
        let found = timeline
            .visible_lines
            .iter()
            .filter(|line| wanted(&line.text))
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "{timeline:?}");
        (found[0].kind, found[0].color.clone())
    };
    let normal = (UiTimelineLineKind::Echo, "#000000".to_owned());
    assert_eq!(line(&|text| text == "plain"), normal);
    assert_eq!(
        line(&|text| text.starts_with('[') && text.ends_with("] red")),
        (UiTimelineLineKind::Echo, "#ff0000".to_owned())
    );
    assert_eq!(line(&|text| text == "said hi"), normal);
    assert_eq!(
        app.dump_model()?
            .submitted_message_commands
            .into_iter()
            .map(|command| command.body)
            .collect::<Vec<_>>(),
        ["hi"]
    );

    type_commands(
        &app,
        &[
            "/echo -s to status",
            "/echo !alpha:example to alpha",
            "/echo -x hi",
        ],
    )?;
    let ui_state = app.dump_ui_state()?;
    assert!(view_contains(
        find_view(&ui_state, &ViewIdentity::Status),
        "to status"
    ));
    assert_eq!(
        view_lines_containing(find_view(&ui_state, &alpha), "to alpha"),
        ["to alpha"]
    );
    assert_switchbar_activity(
        &ui_state,
        &ViewIdentity::Status,
        Some(ViewActivityLevel::Event),
    );
    assert_switchbar_activity(&ui_state, &alpha, Some(ViewActivityLevel::Event));
    assert_switchbar_activity(&ui_state, &beta, None);
    assert!(
        only_view_line_containing(find_view(&ui_state, &beta), "/echo:")
            .ends_with("] * /echo: unknown switch -x")
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn clearall_clears_the_windows_its_switches_name() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    let mut events = base_events_with_a_query();
    // A restore, so Status has lines (and counts the rooms).
    events.insert(1, Event::RestoredSession);
    app.load_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let alpha = room_identity("!alpha:example");
    let beta = room_identity("!beta:example");
    let dm = room_identity("!dm:example");
    app.select_view(alpha.clone())?;
    let has = |ui_state: &UiState, view: &ViewIdentity, text: &str| {
        view_contains(find_view(ui_state, view), text)
    };

    type_commands(&app, &["/clearall -q"])?;
    let ui_state = app.dump_ui_state()?;
    assert!(!has(&ui_state, &dm, "dm first"));
    assert!(has(&ui_state, &alpha, "alpha first"));
    assert!(has(&ui_state, &beta, "beta first"));
    assert!(!find_view(&ui_state, &ViewIdentity::Status).lines.is_empty());

    type_commands(&app, &["/clearall"])?;
    let ui_state = app.dump_ui_state()?;
    assert!(!has(&ui_state, &alpha, "alpha first"));
    assert!(!has(&ui_state, &beta, "beta first"));
    assert!(
        find_view(&ui_state, &ViewIdentity::Status).lines.is_empty(),
        "{:?}",
        find_view(&ui_state, &ViewIdentity::Status).lines
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn room_error_prints_in_room_window() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let beta = room_identity("!beta:example");
    let alpha = room_identity("!alpha:example");
    app.select_view(beta.clone())?;

    app.append_synthetic_events(&serde_json::to_string(&vec![Event::Error(
        mirx_core::CoreErrorEvent {
            operation: mirx_core::Operation::UpdateRoomSettings,
            room_id: Some("!alpha:example".to_owned()),
            message: "not allowed".to_owned(),
        },
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let line = "* Error during change room settings: not allowed";
    let ui_state = app.dump_ui_state()?;
    assert_eq!(ui_state.mdi.active, beta);
    assert!(
        only_view_line_containing(find_view(&ui_state, &alpha), line).ends_with(line),
        "{:?}",
        find_view(&ui_state, &alpha).lines
    );
    assert!(!view_contains(find_view(&ui_state, &beta), line));
    assert!(!view_contains(
        find_view(&ui_state, &ViewIdentity::Status),
        line
    ));
    assert_eq!(
        app.dump_model()?.status,
        "error during change room settings"
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn automation_driver_renders_synced_topic_without_topic_notice()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&serde_json::to_string(&base_events())?)?;

    let mut summary = room_summary("!beta:example", "Beta", false);
    summary.topic = Some("incident review".to_owned());
    app.append_synthetic_events(&serde_json::to_string(&vec![Event::SyncedRooms(vec![
        summary,
    ])])?)?;
    app.wait_idle(Duration::from_secs(5))?;

    let state = app.dump_ui_state()?;
    let beta_view = find_view(&state, &room_identity("!beta:example"));
    assert!(view_contains(beta_view, "* Topic is 'incident review'"));
    assert!(!view_contains(
        beta_view,
        "changes topic to 'incident review'"
    ));

    app.append_synthetic_events(&serde_json::to_string(&vec![topic_event_with_event_id(
        "!beta:example",
        "$beta-topic-summary",
        "@alice:example",
        1_700_000_180_000,
        "deployment window",
    )])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let state = app.dump_ui_state()?;
    let beta_view = find_view(&state, &room_identity("!beta:example"));
    assert!(view_contains(beta_view, "* Topic is 'deployment window'"));
    assert!(view_contains(
        beta_view,
        "changes topic to 'deployment window'"
    ));
    assert!(!view_contains(beta_view, "* Topic is 'incident review'"));

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

