#[test]
fn formatted_messages_render_styled_lines() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let app = launch_app_with_options(
        &exe_path,
        &[OsString::from("--automation")],
        LaunchOptions {
            frame_size: Some(FrameSize {
                width: 800,
                height: 700,
            }),
            ..launch_options(Some(local_app_data.clone()))
        },
    )?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    app.load_events(&fs::read_to_string(fixture_state_path("rich-text.json"))?)?;
    app.wait_idle(Duration::from_secs(5))?;
    app.select_room("!rich:example")?;
    let timeline = active_timeline(&app)?;
    let lines_of = |event_id: &str| {
        timeline
            .visible_lines
            .iter()
            .filter(|line| line.event_id.as_deref() == Some(event_id))
            .collect::<Vec<_>>()
    };
    // The styled text of each span across an event's lines.
    let styled_texts = |lines: &[&mirx_testkit::UiTimelineLine]| {
        lines
            .iter()
            .flat_map(|line| {
                line.styles
                    .iter()
                    .map(|span| line.text[span.start..span.end].to_owned())
            })
            .collect::<Vec<_>>()
    };

    // The styles sit on the body, past the timestamp and nick.
    let first = lines_of("$rich-1");
    assert!(
        first[0].text.starts_with("[22:14] <Alice> bold "),
        "{first:?}"
    );
    assert_eq!((first[0].styles[0].start, first[0].styles[0].end), (16, 20));
    assert!(first[0].styles[0].style.bold);
    assert_eq!(
        styled_texts(&first),
        ["bold", "italic курсив", "underline", "strike", " all"]
    );
    let last_span = first.last().unwrap().styles.last().unwrap();
    assert!(last_span.style.bold && last_span.style.italic && last_span.style.underline);

    // A span crossing a wrap is split between the lines, each part on its own text.
    let wrapped = lines_of("$rich-7");
    assert!(wrapped.len() >= 2, "{wrapped:?}");
    let red = mirx_core::TextColor {
        red: 0xff,
        green: 0,
        blue: 0,
    };
    let red_text = wrapped
        .iter()
        .flat_map(|line| {
            line.styles.iter().map(|span| {
                assert!(span.style.underline);
                assert_eq!(span.style.foreground, Some(red));
                line.text[span.start..span.end].trim().to_owned()
            })
        })
        .collect::<Vec<_>>();
    assert!(red_text.len() >= 2, "{wrapped:?}");
    assert_eq!(
        red_text.join(" "),
        "its red underlined span carries on past the break onto the next line"
    );

    // An edit shows the replacement's styles.
    let edited = lines_of("$rich-10");
    assert_eq!(edited.len(), 1, "{timeline:?}");
    assert_eq!(edited[0].text, "[22:23] <Alice> final text (edited)");
    assert_eq!(styled_texts(&edited), ["text"]);
    assert!(edited[0].styles[0].style.bold);
    assert!(!edited[0].styles[0].style.italic);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// Waits for the active editbox to hold `text`.
fn wait_for_compose_text(app: &MirxApp, text: &str) -> Result<(), Box<dyn std::error::Error>> {
    let deadline = Instant::now() + Duration::from_secs(5);
    while app.compose_text()? != text {
        if Instant::now() >= deadline {
            return Err(
                format!("the editbox holds {:?}, not {text:?}", app.compose_text()?).into(),
            );
        }
        std::thread::sleep(POLL_INTERVAL);
    }
    Ok(())
}

/// The active editbox's selection, in UTF-16 units.
fn compose_selection(app: &MirxApp) -> (usize, usize) {
    let selection = unsafe { SendMessageW(compose_edit_hwnd(app), EM_GETSEL, 0, 0) } as usize;
    (selection & 0xffff, selection >> 16)
}

#[test]
fn ctrl_b_and_e_type_markdown_markers_and_the_line_sends_as_markdown()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_replies_app()?;
    let frame = app.automation_frame_hwnd() as HWND;
    unsafe { SetForegroundWindow(frame) };
    assert_compose_has_focus(&app);
    press_keys(&[VK_CONTROL, u16::from(b'B')]);
    wait_for_compose_text(&app, "****")?;
    assert_eq!(compose_selection(&app), (2, 2));
    press_keys(&[u16::from(b'X')]);
    press_keys(&[VK_END]);
    press_keys(&[VK_CONTROL, u16::from(b'E')]);
    press_keys(&[u16::from(b'Y')]);
    wait_for_compose_text(&app, "**x**~~y~~")?;
    // Markdown has no colour or underline: these keys type nothing.
    for letter in *b"KURO" {
        press_keys(&[VK_CONTROL, u16::from(letter)]);
    }
    press_keys(&[VK_RETURN]);
    wait_for_compose_text(&app, "")?;
    app.wait_idle(Duration::from_secs(5))?;
    let sent = app.dump_model()?.submitted_message_commands;
    assert_eq!(sent.len(), 1, "{sent:?}");
    assert_eq!(sent[0].body, "**x**~~y~~");
    assert_eq!(sent[0].format, mirx_core::ComposeFormat::Markdown);
    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn editbox_format_keys_insert_markdown_markers() -> Result<(), Box<dyn std::error::Error>> {
    let (app, local_app_data) = launch_replies_app()?;
    let edit = unsafe { compose_edit_hwnd(&app) };
    let format = |key: FormatKey| app.send_compose_key(ComposeKey::Format { key });

    app.set_compose_text("ship it now")?;
    unsafe { SendMessageW(edit, EM_SETSEL, 5, 7) };
    format(FormatKey::Bold)?;
    assert_eq!(app.compose_text()?, "ship **it** now");
    assert_eq!(compose_selection(&app), (7, 9));
    format(FormatKey::Italic)?;
    assert_eq!(app.compose_text()?, "ship ***it*** now");
    unsafe { SendMessageW(edit, EM_SETSEL, 14, 17) };
    format(FormatKey::Strikethrough)?;
    assert_eq!(app.compose_text()?, "ship ***it*** ~~now~~");
    app.send_compose_key(ComposeKey::Return)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(app.compose_text()?, "");

    assert_eq!(
        app.dump_model()?.submitted_message_commands,
        vec![SubmittedMessageCommand {
            room_id: "!replies:example".to_owned(),
            presentation: RoomMessagePresentationKind::Text,
            body: "ship ***it*** ~~now~~".to_owned(),
            format: mirx_core::ComposeFormat::Markdown,
            thread: None,
        }]
    );
    // History recalls the line as typed.
    app.send_compose_key(ComposeKey::Up)?;
    assert_eq!(app.compose_text()?, "ship ***it*** ~~now~~");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

// Crash reports.

/// A panic on the UI thread writes crash.log in the profile and ends the
/// process. An automation run never shows the box: the exit within the
/// timeout proves it, as a box would block the abort. The test's stderr
/// shows the default hook's panic message and Wine's line for the abort;
/// both are expected.
#[test]
fn crash_writes_crash_log_and_ends_the_process() -> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    let app = launch_automation_app(&mirx_ui_exe_path()?, &local_app_data)?;

    assert!(app.crash("automation-requested crash").is_err());
    let status = app.end(|app| app.wait_for_exit(Duration::from_secs(20)))?;
    assert!(!status.success(), "{status:?}");

    let log = fs::read_to_string(
        local_app_data
            .join("mirx")
            .join("ui-shell")
            .join("crash.log"),
    )?;
    for expected in [
        format!("mirx {} crashed: ", env!("CARGO_PKG_VERSION")),
        "\r\nThread: main\r\n".to_owned(),
        "\r\nPanic: automation-requested crash\r\n".to_owned(),
        "\r\nAt: crates".to_owned(),
        "\r\nModule base: 0x".to_owned(),
    ] {
        assert!(log.contains(&expected), "{expected:?} in {log}");
    }

    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

// The window buffer (Options > Other).

/// `launch_long_beta_room` with a window buffer of `buffer` lines.
fn launch_buffered_beta_room(
    buffer: u16,
    rows: u64,
) -> Result<(GuiTestApp, MockBackfillHomeserver, PathBuf), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    write_settings(&local_app_data, &format!("[other]\r\nbuffer={buffer}\r\n"))?;
    launch_long_beta_room_in(local_app_data, rows)
}

fn beta_buffer_lines(ui_state: &UiState) -> usize {
    find_ui_room(ui_state, "!beta:example").buffer_lines
}

/// The long-room rows Beta's window shows, by number.
fn beta_history_rows(ui_state: &UiState) -> Vec<u64> {
    find_view(ui_state, &room_identity("!beta:example"))
        .lines
        .iter()
        .filter_map(|line| {
            let (_, number) = line.split_once("history row ")?;
            Some(number.parse().expect("a row number"))
        })
        .collect()
}

#[test]
fn a_window_at_its_end_keeps_the_buffer_and_loads_back_from_its_oldest_line()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(100, 130)?;
    let ui_state = app.dump_ui_state()?;
    // Beta's two first lines and rows 0-29 went.
    assert_eq!(beta_buffer_lines(&ui_state), 100);
    assert_eq!(beta_history_rows(&ui_state), (30..130).collect::<Vec<_>>());
    let lines = &find_view(&ui_state, &room_identity("!beta:example")).lines;
    assert!(
        !lines.iter().any(|line| line.contains("beta first")),
        "{lines:?}"
    );
    assert_eq!(
        find_ui_room(&ui_state, "!beta:example").history_backfill,
        UiRoomHistoryBackfillState::Idle {
            next: HistoryFrom::BeforeEvent {
                event_id: history_row_event_id(30),
            },
        }
    );

    // At the top, the window asks for what it dropped.
    let timeline = app.active_timeline_hwnd()? as HWND;
    send_wheel(timeline, i16::MAX);
    assert_eq!(
        app.dump_model()?.submitted_history_commands,
        vec![SubmittedHistoryCommand {
            room_id: "!beta:example".to_owned(),
            from: HistoryFrom::BeforeEvent {
                event_id: history_row_event_id(30),
            },
            limit: 50,
        }]
    );
    // The mock never answers /messages, so the core stays busy with this
    // backfill and is never idle again: no `wait_idle` from here on.
    app.append_synthetic_events(&serde_json::to_string(&vec![room_history_backfill_event(
        "!beta:example",
        Some("token-older"),
        (10..30)
            .map(|index| history_backfill_event_from_event(history_row(index)))
            .collect(),
    )])?)?;
    // Scrolled back, the window keeps the page above its buffer.
    let ui_state = app.wait_for_ui_state("the older page", Duration::from_secs(5), |ui_state| {
        beta_buffer_lines(ui_state) == 120
    })?;
    assert_eq!(beta_history_rows(&ui_state), (10..130).collect::<Vec<_>>());

    // Back at its end, it drops them again.
    unsafe { SendMessageW(timeline, WM_VSCROLL, SB_BOTTOM as WPARAM, 0) };
    let ui_state = app.wait_for_ui_state("the end", Duration::from_secs(5), |ui_state| {
        beta_buffer_lines(ui_state) == 100
    })?;
    assert_eq!(beta_history_rows(&ui_state), (30..130).collect::<Vec<_>>());
    assert_eq!(
        find_ui_room(&ui_state, "!beta:example").history_backfill,
        UiRoomHistoryBackfillState::Idle {
            next: HistoryFrom::BeforeEvent {
                event_id: history_row_event_id(30),
            },
        }
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn a_log_writes_every_line_of_a_batch_that_overflows_the_buffer()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(100, 0)?;
    type_commands(&app, &["/log on"])?;
    app.append_synthetic_events(&serde_json::to_string(
        &(0..150).map(history_row).collect::<Vec<_>>(),
    )?)?;
    app.wait_idle(Duration::from_secs(5))?;
    // The window keeps its `* Logging on` line and the last 99 rows.
    let ui_state = app.dump_ui_state()?;
    assert_eq!(beta_buffer_lines(&ui_state), 100);
    assert_eq!(beta_history_rows(&ui_state), (51..150).collect::<Vec<_>>());

    let log = read_log(&log_file_path(&local_app_data, "!beta.example"))?;
    let logged = log
        .iter()
        .filter_map(|line| line.split_once("history row ").map(|(_, number)| number))
        .collect::<Vec<_>>();
    assert_eq!(
        logged,
        (0..150)
            .map(|index| format!("{index:03}"))
            .collect::<Vec<_>>()
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn a_window_scrolled_back_keeps_its_lines_until_it_returns_to_its_end()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(100, 100)?;
    assert_eq!(
        beta_history_rows(&app.dump_ui_state()?),
        (0..100).collect::<Vec<_>>()
    );
    let timeline = app.active_timeline_hwnd()? as HWND;
    unsafe { SendMessageW(timeline, WM_VSCROLL, SB_PAGEUP as WPARAM, 0) };
    app.append_synthetic_events(&serde_json::to_string(
        &(100..120).map(history_row).collect::<Vec<_>>(),
    )?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(beta_buffer_lines(&ui_state), 120);
    assert_eq!(beta_history_rows(&ui_state), (0..120).collect::<Vec<_>>());

    unsafe { SendMessageW(timeline, WM_VSCROLL, SB_BOTTOM as WPARAM, 0) };
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(beta_buffer_lines(&ui_state), 100);
    assert_eq!(beta_history_rows(&ui_state), (20..120).collect::<Vec<_>>());
    // It still shows its newest line.
    let last_line = &ui_state
        .active_timeline
        .as_ref()
        .expect("Beta's window has a timeline")
        .visible_lines
        .last()
        .expect("the window shows lines")
        .text;
    assert!(last_line.ends_with("history row 119"), "{last_line}");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

