#[test]
fn an_open_thread_window_keeps_its_lines_in_the_room_window()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(100, 0)?;
    // Rows 0-9, the thread's root, rows 10-89 with a reply after row 11.
    let root_at = 1_700_001_000_000 + 9 * 60_000 + 30_000;
    let mut events = (0..10).map(history_row).collect::<Vec<_>>();
    events.push(message_event_with_event_id(
        "!beta:example",
        "$buffer-root",
        "@bob:example",
        root_at,
        CoreRoomMessagePresentationKind::Text,
        "buffer thread root",
    ));
    events.extend((10..12).map(history_row));
    events.push(message_event_with_event_id_and_relation(
        "!beta:example",
        "$buffer-reply",
        "@bob:example",
        1_700_001_000_000 + 11 * 60_000 + 30_000,
        Some(CoreRoomActivityRelation::Thread {
            thread_root_event_id: "$buffer-root".to_owned(),
            in_reply_to_event_id: Some("$buffer-root".to_owned()),
            is_falling_back: false,
        }),
        CoreRoomMessagePresentationKind::Text,
        "buffer thread reply",
    ));
    events.extend((12..90).map(history_row));
    app.append_synthetic_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(beta_buffer_lines(&app.dump_ui_state()?), 94);

    let thread = thread_identity("!beta:example", "$buffer-root");
    app.select_view(thread.clone())?;
    let thread_lines = find_view(&app.dump_ui_state()?, &thread).lines.clone();
    app.append_synthetic_events(&serde_json::to_string(
        &(90..130).map(history_row).collect::<Vec<_>>(),
    )?)?;
    app.wait_idle(Duration::from_secs(5))?;

    // The room window drops its lines above the root only: its first two
    // and rows 0-9.
    let ui_state = app.dump_ui_state()?;
    assert_eq!(beta_buffer_lines(&ui_state), 122);
    assert_eq!(beta_history_rows(&ui_state), (10..130).collect::<Vec<_>>());
    assert_eq!(find_view(&ui_state, &thread).lines, thread_lines);
    assert!(!ui_state.navigation.find_view(&thread).is_empty());

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn the_status_window_keeps_the_buffer() -> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(100, 0)?;
    app.select_view(ViewIdentity::Status)?;
    // Without their timestamps: the minute may turn during the test.
    let status_lines = |app: &MirxApp| -> Result<Vec<String>, Box<dyn std::error::Error>> {
        Ok(find_view(&app.dump_ui_state()?, &ViewIdentity::Status)
            .lines
            .iter()
            .map(|line| {
                let (_timestamp, text) = line.split_once("] ").expect("a timestamped line");
                text.to_owned()
            })
            .collect())
    };
    let before = status_lines(&app)?;
    type_commands(&app, &["/help"])?;
    let help = status_lines(&app)?[before.len()..].to_vec();
    assert!(!help.is_empty());
    while status_lines(&app)?.len() + help.len() <= 100 {
        type_commands(&app, &["/help"])?;
    }
    type_commands(&app, &["/help"])?;
    let lines = status_lines(&app)?;
    assert_eq!(lines.len(), 100);
    assert_eq!(lines[100 - help.len()..], help[..]);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn a_message_into_a_full_window_builds_it_twice_and_wraps_one_row()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(100, 100)?;
    let before = app.dump_ui_state()?;
    app.append_synthetic_events(&serde_json::to_string(&vec![history_row(100)])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let after = app.dump_ui_state()?;
    assert_eq!(beta_history_rows(&after), (1..101).collect::<Vec<_>>());
    // Built with the new line, then again without the oldest; only the new
    // row is wrapped, and no other window is built.
    let counters = |state: &UiState| state.refresh_counters;
    assert_eq!(
        (
            counters(&after).timeline_row_builds - counters(&before).timeline_row_builds,
            counters(&after).rows_wrapped - counters(&before).rows_wrapped,
            counters(&after).treebar_rebuilds - counters(&before).treebar_rebuilds,
            counters(&after).switchbar_rebuilds - counters(&before).switchbar_rebuilds,
        ),
        (2, 1, 0, 0)
    );
    assert_eq!(
        find_ui_room(&after, "!beta:example").timeline_row_builds
            - find_ui_room(&before, "!beta:example").timeline_row_builds,
        2
    );
    assert_eq!(
        app.dump_ui_state()?.refresh_counters,
        after.refresh_counters
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

// The window menu's Buffer, and /savebuf.

const SYSMENU_ID_BUFFER_CLEAR: WPARAM = 0x0150;
const SYSMENU_ID_BUFFER_SAVE: WPARAM = 0x0160;

fn beta_lines(app: &MirxApp) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    Ok(
        find_view(&app.dump_ui_state()?, &room_identity("!beta:example"))
            .lines
            .clone(),
    )
}

/// A window's lines as a saved buffer holds them.
fn saved_buffer(lines: &[String]) -> String {
    lines.iter().map(|line| format!("{line}\r\n")).collect()
}

#[test]
fn buffer_clear_on_the_window_menu_clears_that_window() -> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(5000, 5)?;
    let ui_state = app.dump_ui_state()?;
    let items = &ui_state.active_system_menu_items;
    let logging = items
        .iter()
        .position(|item| item == "&Logging")
        .expect("Beta's window menu has Logging");
    assert_eq!(
        items[logging..],
        [
            "&Logging",
            "&Buffer",
            "&Buffer/&Clear",
            "&Buffer/&Save...",
            "&Font..."
        ]
    );
    assert!(
        !ui_state
            .active_system_menu_disabled
            .contains(&"&Buffer/&Clear".to_owned())
    );

    // It clears the window whose menu it is, not the active one.
    let beta = view_child_hwnd(&app, &room_identity("!beta:example"))?;
    app.select_view(ViewIdentity::Status)?;
    type_commands(&app, &["/echo -s a line of Status's own"])?;
    let status_lines = find_view(&app.dump_ui_state()?, &ViewIdentity::Status)
        .lines
        .clone();
    assert_ne!(
        unsafe { PostMessageW(beta, WM_SYSCOMMAND, SYSMENU_ID_BUFFER_CLEAR, 0) },
        0
    );
    app.wait_idle(Duration::from_secs(5))?;
    let ui_state = app.dump_ui_state()?;
    assert_eq!(beta_buffer_lines(&ui_state), 0);
    assert!(beta_history_rows(&ui_state).is_empty());
    // The notice leads; the restored session's E2EE status, which the core
    // reports at no fixed moment, may follow it.
    assert_eq!(
        ui_state.status_bar.text.split(" | ").next(),
        Some("cleared window: !beta:example"),
        "{}",
        ui_state.status_bar.text
    );
    assert_eq!(
        find_view(&ui_state, &ViewIdentity::Status).lines,
        status_lines
    );

    // A thread window has nothing of its own to clear.
    app.append_synthetic_events(&serde_json::to_string(&vec![
        message_event_with_event_id(
            "!beta:example",
            "$buffer-root",
            "@bob:example",
            1_700_002_000_000,
            CoreRoomMessagePresentationKind::Text,
            "buffer thread root",
        ),
        message_event_with_event_id_and_relation(
            "!beta:example",
            "$buffer-reply",
            "@bob:example",
            1_700_002_060_000,
            Some(CoreRoomActivityRelation::Thread {
                thread_root_event_id: "$buffer-root".to_owned(),
                in_reply_to_event_id: Some("$buffer-root".to_owned()),
                is_falling_back: false,
            }),
            CoreRoomMessagePresentationKind::Text,
            "buffer thread reply",
        ),
    ])?)?;
    app.wait_idle(Duration::from_secs(5))?;
    app.select_view(thread_identity("!beta:example", "$buffer-root"))?;
    let ui_state = app.dump_ui_state()?;
    assert!(
        ui_state
            .active_system_menu_items
            .contains(&"&Buffer/&Save...".to_owned())
    );
    assert!(
        ui_state
            .active_system_menu_disabled
            .contains(&"&Buffer/&Clear".to_owned()),
        "{:?}",
        ui_state.active_system_menu_disabled
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn savebuf_writes_the_window_lines_to_a_file_in_the_logs_folder_or_anywhere()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(5000, 3)?;
    let lines = beta_lines(&app)?;
    type_commands(&app, &["/savebuf saved beta.txt"])?;
    let saved = local_app_data
        .join("mirx")
        .join("ui-shell")
        .join("logs")
        .join("saved beta.txt");
    assert_eq!(fs::read_to_string(&saved)?, saved_buffer(&lines));
    assert!(lines.iter().any(|line| line.contains("history row 002")));
    assert_eq!(
        app.dump_model()?.status,
        format!("saved buffer: {}", saved.display())
    );

    let anywhere = local_app_data.join("anywhere.txt");
    type_commands(&app, &[&format!("/savebuf {}", anywhere.display())])?;
    assert_eq!(fs::read_to_string(&anywhere)?, saved_buffer(&lines));

    // A file it cannot write says why.
    type_commands(
        &app,
        &[&format!(
            "/savebuf {}",
            local_app_data.join("missing").join("x.txt").display()
        )],
    )?;
    let status = app.dump_model()?.status;
    assert!(status.starts_with("* /savebuf: cannot write "), "{status}");

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

#[test]
fn buffer_save_on_the_window_menu_saves_through_the_save_dialog()
-> Result<(), Box<dyn std::error::Error>> {
    let (app, _server, local_app_data) = launch_buffered_beta_room(5000, 3)?;
    let lines = beta_lines(&app)?;
    let beta = view_child_hwnd(&app, &room_identity("!beta:example"))?;
    let frame = app.automation_frame_hwnd() as HWND;

    // Cancel saves nothing.
    assert_ne!(
        unsafe { PostMessageW(beta, WM_SYSCOMMAND, SYSMENU_ID_BUFFER_SAVE, 0) },
        0
    );
    let (dialog, caption) = wait_for_owned_dialog(frame);
    assert_eq!(caption, "Save Buffer");
    let name = unsafe { GetDlgItem(dialog, OPEN_DIALOG_FILE_NAME_ID) };
    assert!(!name.is_null(), "the Save dialog has its file name box");
    // The window's log name.
    assert_eq!(unsafe { read_window_text(name) }, "!beta.example.txt");
    let status_before = app.dump_model()?.status;
    answer_message_box(&app, dialog, IDCANCEL)?;
    assert_eq!(app.dump_model()?.status, status_before);

    assert_ne!(
        unsafe { PostMessageW(beta, WM_SYSCOMMAND, SYSMENU_ID_BUFFER_SAVE, 0) },
        0
    );
    let (dialog, _) = wait_for_owned_dialog(frame);
    let saved = local_app_data.join("chosen.txt");
    let name = unsafe { GetDlgItem(dialog, OPEN_DIALOG_FILE_NAME_ID) };
    let text = wide_null(saved.to_str().expect("UTF-8 test path"));
    unsafe { SendMessageW(name, WM_SETTEXT, 0, text.as_ptr() as isize) };
    answer_message_box(&app, dialog, IDOK)?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(fs::read_to_string(&saved)?, saved_buffer(&lines));
    assert_eq!(
        app.dump_model()?.status,
        format!("saved buffer: {}", saved.display())
    );

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

const CHANNEL_CENTRAL_NAME_ID: i32 = 7601;
const CHANNEL_CENTRAL_TOPIC_ID: i32 = 7602;
const CHANNEL_CENTRAL_BANS_ID: i32 = 7603;
const CHANNEL_CENTRAL_REMOVE_ID: WPARAM = 7604;
const CHANNEL_CENTRAL_TOPIC_BY_OPERATORS_ID: i32 = 7605;
const CHANNEL_CENTRAL_INVITE_ONLY_ID: i32 = 7606;
const CHANNEL_CENTRAL_MODERATED_ID: i32 = 7607;

/// Waits for Channel Central to show and to have the core's answer (the
/// settings or an error) in its status line.
fn wait_for_channel_central(
    app: &MirxApp,
) -> Result<(HWND, UiChannelCentral), Box<dyn std::error::Error>> {
    let dialog = wait_for_window(&wide_null("mirxWin32ChannelCentralDialog"), "Room Settings")?;
    let ui_state = app.wait_for_ui_state(
        "Room Settings' answer",
        Duration::from_secs(30),
        |ui_state| {
            ui_state
                .channel_central
                .as_ref()
                .is_some_and(|central| central.status != "Reading the room's settings...")
        },
    )?;
    Ok((dialog, ui_state.channel_central.expect("waited for above")))
}

fn channel_central(app: &MirxApp) -> Result<UiChannelCentral, Box<dyn std::error::Error>> {
    Ok(app
        .dump_ui_state()?
        .channel_central
        .ok_or("Channel Central is open")?)
}

fn set_dialog_check(dialog: HWND, id: i32, checked: bool) {
    unsafe { SendMessageW(GetDlgItem(dialog, id), BM_SETCHECK, usize::from(checked), 0) };
}

/// mIRC's Channel Central (`/channel`): the room's settings as the server
/// has them, and OK writes what changed, the two power-level modes in one
/// write; the server's echo prints the lines.
#[test]
fn channel_central_shows_and_changes_the_room_settings() -> Result<(), Box<dyn std::error::Error>> {
    let local_app_data = unique_local_app_data_path();
    let server = spawn_mock_backfill_homeserver()?;
    write_saved_session(&local_app_data, &server.base_url)?;
    let app = launch_with_saved_session(&local_app_data)?;
    wait_until_connected(&app)?;
    wait_for_beta_and_bob(&app)?;
    let beta = room_identity("!beta:example");
    app.select_view(beta.clone())?;
    assert!(app.dump_room_menu_state()?.channel_central_enabled);

    app.set_compose_text("/channel")?;
    app.open_dialog(AutomationDialog::ComposeReturn)?;
    let (dialog, central) = wait_for_channel_central(&app)?;
    assert_eq!(central.caption, "Room Settings - Beta");
    assert_eq!(central.room_id, "!beta:example");
    // Alice is the room's 100: everything is hers to change.
    assert_eq!(central.status, "");
    assert_eq!(central.name, "Beta");
    assert_eq!(central.topic, "Beta's topic");
    assert_eq!(central.topic_items, ["Beta's topic"]);
    assert_eq!(central.ban_rows.len(), 1, "{:?}", central.ban_rows);
    let ban = &central.ban_rows[0];
    assert_eq!(ban[0], "@carol:example");
    assert_eq!(ban[1], "Alice");
    // `dd/mm/yyyy HH:nn` in the local time.
    assert_eq!(ban[2].len(), 16, "{ban:?}");
    assert_eq!(&ban[2][2..3], "/", "{ban:?}");
    assert_eq!(ban[3], "spam");
    // The spec's default levels: only ops (50) set the topic.
    assert_eq!(central.topic_by_operators.state, UiCheckState::Checked);
    assert_eq!(central.invite_only.state, UiCheckState::Checked);
    assert_eq!(central.moderated.state, UiCheckState::Unchecked);
    assert_eq!(central.private.state, UiCheckState::Checked);
    assert!(
        [
            central.topic_by_operators,
            central.invite_only,
            central.moderated,
            central.private
        ]
        .iter()
        .all(|check| check.enabled)
    );
    assert!(central.name_enabled && central.topic_enabled && central.ok_enabled);
    assert!(!central.remove_enabled, "no ban is selected");

    set_dialog_check(dialog, CHANNEL_CENTRAL_TOPIC_BY_OPERATORS_ID, false);
    set_dialog_check(dialog, CHANNEL_CENTRAL_MODERATED_ID, true);
    set_dialog_check(dialog, CHANNEL_CENTRAL_INVITE_ONLY_ID, false);
    set_dialog_text(dialog, CHANNEL_CENTRAL_TOPIC_ID, "A new topic");
    let bans = unsafe { GetDlgItem(dialog, CHANNEL_CENTRAL_BANS_ID) };
    post_left_click(bans, &central.ban_row_click_points[0], false);
    app.wait_for_ui_state("the ban selected", Duration::from_secs(5), |ui_state| {
        ui_state
            .channel_central
            .as_ref()
            .is_some_and(|central| central.remove_enabled)
    })?;
    post_dialog_command(dialog, CHANNEL_CENTRAL_REMOVE_ID);
    app.wait_for_ui_state("the ban removed", Duration::from_secs(5), |ui_state| {
        ui_state
            .channel_central
            .as_ref()
            .is_some_and(|central| central.ban_rows.is_empty() && !central.remove_enabled)
    })?;
    // Only the dialog's own edits: unchecked above, Private stays.
    let central = channel_central(&app)?;
    assert_eq!(central.topic_by_operators.state, UiCheckState::Unchecked);
    assert_eq!(central.private.state, UiCheckState::Checked);

    post_dialog_command(dialog, IDOK as WPARAM);
    wait_for_window_gone(dialog, "Room Settings")?;
    app.wait_idle(Duration::from_secs(5))?;
    let model = app.dump_model()?;
    assert_eq!(model.status, "room settings sent");
    assert_eq!(
        model.submitted_room_settings_commands,
        [
            SubmittedRoomSettingsCommand::Fetch {
                room_id: "!beta:example".to_owned(),
            },
            SubmittedRoomSettingsCommand::Update {
                room_id: "!beta:example".to_owned(),
                topic_by_operators: Some(false),
                moderated: Some(true),
                member_roles: Vec::new(),
                invite_only: Some(false),
                name: None,
                topic: Some("A new topic".to_owned()),
                listed_in_directory: None,
                unban: vec!["@carol:example".to_owned()],
            },
        ]
    );

    // The server got them in the request's order, the modes in one write.
    let writes = server.wait_for_settings_writes(4)?;
    let paths = writes
        .iter()
        .map(|(path, _)| path.as_str())
        .collect::<Vec<_>>();
    assert_eq!(
        paths,
        [
            "PUT state/m.room.power_levels/",
            "PUT state/m.room.join_rules/",
            "PUT state/m.room.topic/",
            "POST unban",
        ]
    );
    let power_levels = &writes[0].1;
    assert_eq!(power_levels["events_default"], 1, "{power_levels}");
    assert_eq!(power_levels["events"]["m.room.topic"], 0, "{power_levels}");
    assert_eq!(
        power_levels["users"],
        serde_json::json!({ "@alice:example": 100, "@bob:example": 50 })
    );
    assert_eq!(writes[1].1["join_rule"], "public");
    assert_eq!(writes[2].1["topic"], "A new topic");
    assert_eq!(writes[3].1["user_id"], "@carol:example");

    // The server's echo prints the lines.
    let echo = |event_type: &str, event_id: &str, content: serde_json::Value| {
        serde_json::json!({
            "content": content,
            "event_id": event_id,
            "origin_server_ts": 1700000000100u64,
            "sender": "@alice:example",
            "state_key": "",
            "type": event_type
        })
    };
    server.append_timeline(echo(
        "m.room.join_rules",
        "$join-rules-echo",
        serde_json::json!({ "join_rule": "public" }),
    ));
    server.append_timeline(echo(
        "m.room.name",
        "$name-echo",
        serde_json::json!({ "name": "Gamma" }),
    ));
    wait_for_view_lines_with(&app, &beta, "* Alice makes the room public", 1)?;
    wait_for_view_lines_with(&app, &beta, "* Alice changes room name to 'Gamma'", 1)?;

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// A double-click in a channel window, off a link and a quote, opens
/// Channel Central, as mIRC's does; Cancel sends nothing. In Status it
/// opens nothing. (The link and quote double-clicks are pinned by their
/// own tests.)
#[test]
fn double_click_in_a_room_opens_channel_central() -> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    let mut events = base_events();
    events.insert(
        1,
        Event::LoggedIn {
            session: core_stored_session(),
            homeserver_url: "https://matrix.example/".to_owned(),
        },
    );
    app.load_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    app.select_view(room_identity("!beta:example"))?;
    assert!(app.dump_room_menu_state()?.channel_central_enabled);

    let point = text_point(&app, "beta second", 2)?;
    send_left_click(app.active_timeline_hwnd()? as HWND, &point, true);
    let (dialog, central) = wait_for_channel_central(&app)?;
    assert_eq!(central.caption, "Room Settings - Beta");
    // This core has no session: the read's error, and nothing to change.
    assert_eq!(
        central.status,
        "fetch room settings requires an authenticated session"
    );
    assert!(!central.ok_enabled && !central.name_enabled && !central.topic_by_operators.enabled);
    post_dialog_command(dialog, IDCANCEL as WPARAM);
    wait_for_window_gone(dialog, "Room Settings")?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(
        app.dump_model()?.submitted_room_settings_commands,
        [SubmittedRoomSettingsCommand::Fetch {
            room_id: "!beta:example".to_owned(),
        }]
    );

    app.select_view(ViewIdentity::Status)?;
    let timeline = app
        .dump_ui_state()?
        .active_timeline
        .ok_or("Status has a timeline")?;
    let line = timeline
        .visible_lines
        .iter()
        .find(|line| line.links.is_empty())
        .ok_or_else(|| format!("a line without links: {:?}", timeline.visible_lines))?;
    send_left_click(app.active_timeline_hwnd()? as HWND, &line.click_point, true);
    app.wait_idle(Duration::from_secs(5))?;
    assert!(
        app.wait_for_modal_dialog(Duration::from_millis(500))
            .is_err()
    );
    assert_eq!(app.dump_model()?.submitted_room_settings_commands.len(), 1);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

/// A channel double-click opens Channel Central for the window clicked,
/// even if another one becomes active before the dialog opens: here an
/// activation posted after the click, which the frame handles before the
/// click's own posted message.
#[test]
fn a_channel_double_click_opens_channel_central_of_the_clicked_window()
-> Result<(), Box<dyn std::error::Error>> {
    let exe_path =
        mirx_ui_exe_path().map_err(|error| format!("failed to locate mirx-ui.exe: {error}"))?;
    let local_app_data = unique_local_app_data_path();
    let options = launch_options(Some(local_app_data.clone()));
    let app = launch_app_with_options(&exe_path, &[OsString::from("--automation")], options)?;
    app.wait_for_lifecycle_state("core_started", Duration::from_secs(30))?;
    let mut events = base_events();
    events.insert(
        1,
        Event::LoggedIn {
            session: core_stored_session(),
            homeserver_url: "https://matrix.example/".to_owned(),
        },
    );
    app.load_events(&serde_json::to_string(&events)?)?;
    app.wait_idle(Duration::from_secs(5))?;
    let alpha = room_identity("!alpha:example");
    let beta = room_identity("!beta:example");
    app.select_view(alpha.clone())?;
    let point = text_point(&app, "alpha first", 2)?;
    let timeline = app.active_timeline_hwnd()? as HWND;
    let beta_child = view_child_hwnd(&app, &beta)?;

    // Posted, all of them: the queue keeps their order.
    let lparam = mouse_lparam(&point);
    for (message, buttons) in [
        (WM_LBUTTONDOWN, MK_LBUTTON),
        (WM_LBUTTONUP, 0),
        (WM_LBUTTONDBLCLK, MK_LBUTTON),
        (WM_LBUTTONUP, 0),
    ] {
        assert_ne!(
            unsafe { PostMessageW(timeline, message, buttons as WPARAM, lparam) },
            0
        );
    }
    assert_ne!(
        unsafe {
            PostMessageW(
                mdi_client_hwnd(&app),
                WM_MDIACTIVATE,
                beta_child as WPARAM,
                0,
            )
        },
        0
    );
    let (dialog, central) = wait_for_channel_central(&app)?;
    assert_eq!(
        (central.room_id.as_str(), central.caption.as_str()),
        ("!alpha:example", "Room Settings - Alpha")
    );
    post_dialog_command(dialog, IDCANCEL as WPARAM);
    wait_for_window_gone(dialog, "Room Settings")?;
    app.wait_idle(Duration::from_secs(5))?;
    assert_eq!(app.dump_ui_state()?.mdi.active, beta);

    drop(app);
    let _ = fs::remove_dir_all(&local_app_data);
    Ok(())
}

